"use strict";(self.webpackChunk_N_E=self.webpackChunk_N_E||[]).push([[2032],{62032:function(e,t,n){n.d(t,{OI:function(){return s},Wq:function(){return o},S2:function(){return r}});let a=JSON.parse('[{"id":"article-e2e-high-throughput-e-commerce-inventory-and-checkout","slug":"e2e-high-throughput-e-commerce-inventory-and-checkout","title":"Designing End-to-End High Throughput E-Commerce Inventory and Checkout","subtitle":"A step-by-step scenario combining Caching, Distributed Locking, and Database Sharding for flash sales","summary":"Explore how top-tier retail platforms process 50,000 requests per second during flash sales using multi-tier caching, Redis distributed locks, and database sharding without double-booking or lock starvation.","author":{"name":"Abstract Algorithms Engineering Team","avatarUrl":"/images/authors/team.png"},"publishedAt":"2026-10-05T00:00:00Z","updatedAt":"2026-10-05T00:00:00Z","linkedConceptSlugs":["caching","distributed-locking","database-sharding"],"useCase":{"goal":"Process 50,000 checkout reservations/sec with sub-50ms latency while guaranteeing zero double-allocations during peak flash sale events.","actorsAndComponents":["Buyer Client (Web / Mobile)","API Gateway (Edge Router)","Catalog & Inventory Read Cache (Redis Cluster)","Distributed Lock Service (Redlock / Redis Cluster)","Sharded Inventory Database (PostgreSQL Shard Cluster)"],"requirements":["Sub-50ms p99 latency for inventory availability queries and reservation claims.","Strict zero-oversell guarantee: ticket count can never drop below 0.","High availability: system tolerates single-node Redis or DB shard master failures without cascading outages."],"constraints":["Flash sale window opens simultaneously across multiple geographic regions.","Database shards are partitioned by Product ID (SKU).","Maximum 500 DB connection pool capacity per shard."],"assumptions":["Product inventory is pre-warmed into Redis read caches 15 minutes before sale start.","Buyers hold items for a maximum 10-minute payment grace period before stock auto-releases."]},"stages":[{"stageNumber":1,"title":"Stage 1: High-Speed Read-Through Inventory Check via Redis Cache","decisionOrAction":"Buyer navigates to SKU page. System queries multi-tier read-through cache for stock availability.","linkedConceptSlugs":["caching"],"conceptRoles":[{"conceptSlug":"caching","roleDescription":"Offloads 98% of read queries from primary database shards using Cache-Aside and TTL-based invalidation."}],"componentBehavior":"API Gateway forwards GET /inventory/:sku to Read Cache Service. Service returns cached item stock count.","observableOutput":"HTTP 200 OK returned in 8ms with payload { sku: \\"SKU-991\\", available: 120, cacheHit: true }."},{"stageNumber":2,"title":"Stage 2: Acquiring Distributed Lock for Stock Reservation","decisionOrAction":"Buyer clicks \\"Reserve Item\\". System requests non-blocking distributed lock on SKU resource lock key.","linkedConceptSlugs":["distributed-locking"],"conceptRoles":[{"conceptSlug":"distributed-locking","roleDescription":"Ensures exclusive single-thread access per SKU reservation decrement to prevent race conditions across parallel app instances."}],"componentBehavior":"Inventory Microservice issues SET sku:lock:SKU-991 PX 3000 NX to Redis cluster. Lock acquired with 3-second auto-expiry.","observableOutput":"Lock acquired in 5ms. Thread proceeds to database transactional decrement stage."},{"stageNumber":3,"title":"Stage 3: Executing Sharded Database Decrement & Releasing Lock","decisionOrAction":"Transaction executed on target DB shard based on SKU hash partition.","linkedConceptSlugs":["database-sharding"],"conceptRoles":[{"conceptSlug":"database-sharding","roleDescription":"Distributes transactional writes across 16 database shards, removing single-primary database bottlenecks."}],"componentBehavior":"Inventory service routes UPDATE stock SET quantity = quantity - 1 WHERE sku = \\"SKU-991\\" AND quantity > 0 to Shard 7. Releases Redis lock after commit.","observableOutput":"Transaction committed in 14ms. Stock count updated to 119. Lock safely released via Lua script comparison."}],"outcome":{"endToEndResult":"Successfully handles 50,000 requests/sec with p99 latency of 27ms and zero inventory double-allocations.","observedUserBehavior":"Buyers experience immediate response feedback with seamless ticket reservation confirmation.","observedOperatorBehavior":"Operators observe balanced CPU loads across all 16 DB shards and stable 12% cache miss rate.","keyTradeoffs":["Eventual consistency on read cache during rapid inventory changes vs strict transactional lock overhead on database write shards.","3-second distributed lock timeout prevents deadlock if worker crashes but risks concurrent execution if DB write exceeds 3 seconds."]},"alternatives":[{"title":"Single Monolithic Database with Pessimistic Row Locking (SELECT FOR UPDATE)","explanation":"Simpler architecture without Redis locks or sharding, but fails under >2,000 RPS due to lock contention and connection pool exhaustion."},{"title":"Asynchronous Event Sourcing via Queue (Kafka)","explanation":"Decouples reservations into message queues. Highly available but forces asynchronous user feedback (buyers wait for email notification instead of instant confirmation)."}],"failuresAndDegradedModes":[{"name":"Redis Cache Node Failure","behavior":"Read requests fallback to database replica instances with rate limiting enabled, maintaining system stability at reduced throughput."},{"name":"Distributed Lock Timeout Expiry","behavior":"If DB shard write stalls beyond 3s, lock auto-expires. Database transaction check `WHERE quantity > 0` acts as secondary safety barrier against negative stock."}],"evidenceRecord":{"isSourcedProductionClaim":false,"statedAssumptions":["Assumes 16 database shards with uniform SKU hash distribution.","Assumes Redis cluster deployed across 3 Availability Zones."],"illustrativeTeachingLabel":"Illustrative System Architecture Case Study (Modeled after High-Scale Flash Sale Architecture)"},"reviewStatus":"canonical","reviewerName":"Principal Distributed Systems Architect","reviewedAt":"2026-10-05T00:00:00Z","tags":["system-design","e-commerce","flash-sale","caching","sharding","distributed-locks"],"markdownContent":"\\n## Key learnings\\n\\n- Separate the hot read path (cache) from the exclusive claim path (distributed lock) so flash-sale traffic does not serialize on the database.\\n- A lock without a short TTL and explicit release path becomes an availability outage; treat abandonment as a first-class failure mode.\\n- Shard inventory by SKU so write contention stays local; a global inventory lock does not survive peak concurrency.\\n- Cache hits are not reservations — only a successful claim against authoritative stock should confirm checkout.\\n- Measure p99 reservation latency and oversell rate together; optimizing one without the other hides the real risk.\\n"},{"id":"article-acid-properties-in-sql-databases","slug":"acid-properties-in-sql-databases","title":"ACID Properties Explained: How SQL Databases Guarantee Atomicity, Consistency, Isolation, and Durability","subtitle":"A deep dive into PostgreSQL WAL logs, MVCC snapshot isolation, Write Skew anomalies, and crash recovery","summary":"Trace how storage engines process high-stakes financial transactions like bank transfers using Write-Ahead Logging (WAL), Multi-Version Concurrency Control (MVCC), and SSI locks without data loss or corruption.","author":{"name":"Abstract Algorithms Database Team","avatarUrl":"/images/authors/team.png"},"publishedAt":"2026-10-07T00:00:00Z","updatedAt":"2026-10-07T00:00:00Z","linkedConceptSlugs":["database-isolation-levels-anomalies","transaction-isolation-distributed-acid"],"useCase":{"goal":"Execute a $500 account transfer concurrently while preventing Write Skew anomalies, uncommitted data visibility, and post-crash state corruption.","actorsAndComponents":["Bank API Server (Application Layer)","Shared Memory Buffer Pool (DB RAM)","Write-Ahead Log (WAL Writer & fsync)","Disk Storage Engine (Heap Pages)","Crash Recovery Manager (REDO / UNDO Scanner)"],"requirements":["Atomicity: Debit from Account A and credit to Account B must both succeed or both roll back completely.","Consistency: Enforce invariants (e.g. balance >= 0) even under concurrent execution.","Isolation: Prevent dirty reads, non-repeatable reads, and write skew under concurrent traffic.","Durability: Ensure committed transfers persist across unexpected hardware power losses."],"constraints":["Direct disk writes on every row mutation cause unacceptably high disk I/O latency.","Read operations cannot block write operations under heavy OLTP traffic."],"assumptions":["PostgreSQL flushes WAL records to disk via fsync before modifying buffer pool pages.","Transactions run under Serializable snapshot isolation (SSI) when preventing write skew."]},"stages":[{"stageNumber":1,"title":"Stage 1: Sequential WAL Record Flushing for Atomicity & Durability","decisionOrAction":"App issues debit account_A by $500. WAL record is written sequentially to disk before buffer pool modification.","linkedConceptSlugs":["transaction-isolation-distributed-acid"],"conceptRoles":[{"conceptSlug":"transaction-isolation-distributed-acid","roleDescription":"The transaction boundary groups the debit, credit, and commit decision so partial database work is not exposed as a completed transfer."}],"componentBehavior":"WAL writer issues sequential log write and calls fsync. Page updated in buffer pool RAM.","observableOutput":"WAL record durable on disk. Dirty page marked in shared buffer pool in 2ms."},{"stageNumber":2,"title":"Stage 2: MVCC Snapshotting & Isolation Anomaly Prevention","decisionOrAction":"Concurrent transactions attempt to read and update account balances simultaneously.","linkedConceptSlugs":["database-isolation-levels-anomalies"],"conceptRoles":[{"conceptSlug":"database-isolation-levels-anomalies","roleDescription":"Isolation levels determine which concurrent anomalies can occur and whether a conflicting transaction must retry."}],"componentBehavior":"Database assigns transaction ID snapshot (xmin/xmax). Concurrent reads see isolated tuple snapshot without waiting for lock release.","observableOutput":"Read queries return in 1ms with clean transaction snapshot state."},{"stageNumber":3,"title":"Stage 3: Crash Recovery & Automatic Aborted Transaction Rollback","decisionOrAction":"Power failure occurs before transaction COMMIT record is written. Server reboots.","linkedConceptSlugs":["transaction-isolation-distributed-acid"],"conceptRoles":[{"conceptSlug":"transaction-isolation-distributed-acid","roleDescription":"The database recovers committed work from its log and discards incomplete work according to its engine-specific recovery protocol."}],"componentBehavior":"Recovery scanner finds no COMMIT record for txn-8821. Pre-transaction state restored on heap page.","observableOutput":"Account A balance safely restored to pre-transaction value without state leakage."}],"outcome":{"endToEndResult":"Guarantees 100% financial correctness, zero lost updates, and complete crash resilience under concurrent load.","observedUserBehavior":"Users receive instant atomic transaction responses without visible intermediate corrupt state.","observedOperatorBehavior":"Operators observe stable recovery on reboot with zero disk corruption errors.","keyTradeoffs":["Immediate WAL fsync guarantees zero data loss but adds sequential disk wait latency per transaction.","Serializable snapshot isolation eliminates all anomalies but requires client retry handling under high conflict rates."]},"alternatives":[{"title":"Exclusive Table-Level Locking (Pessimistic Locking)","explanation":"Simplest concurrency model, but restricts system throughput to single-threaded sequential execution."},{"title":"Asynchronous Background Log Flushing","explanation":"Improves transaction throughput by 5x, but risks losing the last few milliseconds of committed data during power failure."}],"failuresAndDegradedModes":[{"name":"Server Power Loss During Active Transfer","behavior":"WAL recovery process detects missing COMMIT record on reboot and rolls back uncommitted dirty pages to pre-transaction state."},{"name":"Write Skew Under Read Committed Isolation","behavior":"Concurrent transactions bypass balance check. Mitigation requires upgrading to Serializable isolation or SELECT FOR UPDATE."}],"evidenceRecord":{"isSourcedProductionClaim":true,"sourceUrlOrAttribution":"https://www.postgresql.org/docs/current/wal-intro.html","statedAssumptions":["Assumes POSIX-compliant file system fsync behavior."]},"markdownContent":"\\n## A transfer is one decision, even when the database performs many writes\\n\\nImagine a bank transferring $500 from account A to account B. The application must debit one row and credit another. A process crash between those writes must not leave money missing; two concurrent transfers must not both spend the same balance; and once the database confirms a commit, a restart must not erase it.\\n\\nACID names four guarantees that make this transaction dependable. They solve different problems, and no single setting or storage structure provides all four. We will follow one transfer through validation, concurrent execution, commit, and recovery to see where each guarantee comes from.\\n\\n```mermaid\\nsequenceDiagram\\n    title Banking Transaction ACID Lifecycle\\n    participant App as Banking API\\n    participant DB as SQL Database\\n    participant WAL as Durable Log\\n    participant Disk as Data Files\\n    App->>DB: BEGIN; debit A; credit B\\n    DB->>DB: Check constraints and isolation\\n    DB->>WAL: Append transaction records\\n    WAL-->>DB: Commit record is durable\\n    DB-->>App: COMMIT acknowledged\\n    Note over WAL,Disk: Data pages may be written later; recovery replays durable log records\\n```\\n\\nThe important ordering is that a database can acknowledge a commit before every changed table page reaches its final location. It first makes the log record durable according to its configured guarantee. Recovery uses that record after a crash. This is why a database can combine fast sequential log writes with safe updates to many data pages.\\n\\n## Stage 1 — Atomicity: make the transfer all-or-nothing\\n\\nThe application starts a transaction, debits account A, credits account B, and commits. If the second update fails or the process aborts before commit, the database rolls back the first update. Atomicity describes the result visible to the transaction’s participants: both changes commit, or neither does.\\n\\nDatabases use transaction logs and recovery records to implement this behavior. PostgreSQL’s write-ahead log (WAL) records changes so crash recovery can redo committed work and discard incomplete work. InnoDB uses redo logging for recovery and undo records to roll back transactions and provide older row versions. The details differ by engine, but the application-level guarantee is the same.\\n\\n```sql\\nBEGIN;\\n\\nUPDATE accounts\\nSET balance = balance - 500\\nWHERE account_id = \'A\' AND balance >= 500;\\n\\n-- The application checks that exactly one row was updated.\\nUPDATE accounts\\nSET balance = balance + 500\\nWHERE account_id = \'B\';\\n\\nCOMMIT;\\n```\\n\\nThe first update’s predicate is part of the business rule, but the application must still verify the affected-row count and roll back if the debit did not happen. A transaction boundary cannot repair incorrect application logic by itself.\\n\\n## Stage 2 — Consistency: preserve invariants at transaction boundaries\\n\\nConsistency means a committed transaction leaves the database in a state that satisfies the rules the application and schema define. It is not a promise that every business rule is automatically known to the database. Put durable invariants in constraints where possible, and validate the remaining rules in transaction logic.\\n\\nFor example, a `CHECK (balance >= 0)` constraint prevents a committed negative balance. A foreign key can ensure that a transfer references existing accounts. Some rules depend on multiple rows and need locking or serializable execution; a row-level check alone cannot enforce every cross-row invariant.\\n\\n```sql\\nCREATE TABLE accounts (\\n  account_id text PRIMARY KEY,\\n  balance numeric(12, 2) NOT NULL CHECK (balance >= 0)\\n);\\n\\nCREATE TABLE transfers (\\n  transfer_id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,\\n  from_account text NOT NULL REFERENCES accounts(account_id),\\n  to_account text NOT NULL REFERENCES accounts(account_id),\\n  amount numeric(12, 2) NOT NULL CHECK (amount > 0)\\n);\\n```\\n\\nThe C in ACID is about application-defined validity of committed data. It is different from consistency in the CAP theorem, which concerns whether distributed replicas return the same view during network partitions.\\n\\n## Stage 3 — Isolation: define what concurrent transactions can observe\\n\\nWhile the transfer runs, another request may read the accounts or attempt a competing withdrawal. Isolation controls which effects concurrent transactions can observe and which anomalies the database prevents. Implementations commonly combine locks, multiversion concurrency control (MVCC), or both.\\n\\nWith MVCC, a reader can often see a stable snapshot while writers create newer row versions. This improves read/write concurrency, but the exact anomalies prevented depend on the isolation level and database engine. PostgreSQL `REPEATABLE READ` uses snapshot isolation and can still allow write skew; PostgreSQL `SERIALIZABLE` uses Serializable Snapshot Isolation to detect dangerous dependency patterns and abort one transaction when necessary. Other engines define their isolation behavior differently, so applications should consult the engine’s documentation rather than infer guarantees from the level name alone.\\n\\n```mermaid\\nsequenceDiagram\\n    title Serializable Transaction Isolation Validation\\n    participant T1 as Transaction 1\\n    participant T2 as Transaction 2\\n    participant DB as Database\\n    T1->>DB: Read invariant and current rows\\n    T2->>DB: Read overlapping snapshot\\n    T1->>DB: Write row A\\n    T2->>DB: Write row B\\n    DB->>DB: Validate conflicts at serializable commit\\n    DB-->>T1: Commit, or serialization failure\\n    DB-->>T2: Commit, or serialization failure\\n```\\n\\nSerializable transactions may be retried after a serialization failure. That retry must repeat the whole transaction from a fresh snapshot and must not duplicate external side effects. If the application sends a payment-provider request inside the transaction, use an idempotency key or an outbox-style handoff so a database retry does not charge twice.\\n\\n## Stage 4 — Durability: make an acknowledged commit survive the failures you promise to handle\\n\\nDurability means committed work survives failures covered by the database’s operating and storage assumptions. In PostgreSQL, WAL records are flushed before the corresponding changed data pages need to be written. A restart replays durable records to reconstruct committed state. Group commit can amortize a flush across multiple transactions.\\n\\nThe guarantee depends on configuration and infrastructure. For example, PostgreSQL `synchronous_commit` and InnoDB `innodb_flush_log_at_trx_commit` affect when commit acknowledgements wait for log flushing. Disabling or weakening a flush may improve latency, but can lose recently acknowledged transactions after a host or power failure. Replication durability is a separate choice: local log durability does not by itself guarantee that another region has received the commit.\\n\\n``\\n    A[Transaction changes rows] --> B[Append log records]\\n    B --> C{Commit record flushed?}\\n    C -->|Yes| D[Return commit acknowledgement]\\n    C -->|No| E[Do not claim durable commit]\\n    D --> F[Write data pages later]\\n    F --> G[Checkpoint limits recovery work]\\n    H[Crash and restart] --> I[Replay durable committed log]\\n    I --> J[Discard incomplete transaction effects]\\n```\\n\\n## How the four guarantees work together\\n\\n| Failure or pressure | Guarantee involved | Database/application response |\\n| --- | --- | --- |\\n| Credit update fails after debit | Atomicity | Roll back the transaction |\\n| Debit would violate a balance rule | Consistency | Reject through a constraint or validated transaction rule |\\n| Two withdrawals race | Isolation | Lock, serialize, or abort one transaction for retry |\\n| Host crashes after commit acknowledgement | Durability | Recover acknowledged work from durable log records, within configured assumptions |\\n\\nACID is therefore a composition of transaction boundaries, constraints, concurrency control, and recovery. A transaction can be atomic but still commit a logically invalid result if the application never checked the right invariant. A schema can enforce consistency while a weak isolation level still permits a race. A correct isolated transaction can still lose acknowledged work if durability settings do not match the failure promise.\\n\\n## Choosing isolation and durability deliberately\\n\\nStart with the invariant and failure model, then choose settings that satisfy them. Use constraints for row-local rules. Use explicit locking or serializable isolation when correctness depends on concurrent decisions across rows. Handle serialization failures as expected retryable outcomes. Keep durable commit flushing enabled for transactions whose acknowledgements must survive a host crash, and document any weaker guarantee for disposable or rebuildable data.\\n\\nMeasure the actual workload before trading correctness for throughput. WAL flush latency, lock contention, transaction length, checkpoint activity, and retry rates point to different bottlenecks. Group commit, batching, shorter transactions, and appropriate indexes can improve throughput without silently changing the failure guarantee.\\n\\n## What this scenario does not guarantee\\n\\nACID applies to the database transaction’s committed state. It does not automatically make a payment provider call atomic with the database, guarantee cross-region replication, prevent every application bug, or make backups unnecessary. Those require additional design: idempotency, outbox/inbox processing, replication policies, validation, and tested backups.\\n\\nThe transfer is safe when its schema expresses durable invariants, its transaction includes all database writes that must succeed together, its isolation level prevents the relevant races, and its commit configuration matches the failure promise made to callers. That is the practical meaning of ACID: a precise contract between the application, database engine, and storage system.\\n\\n## Key learnings\\n\\n- ACID is four contracts, not one feature: atomicity, consistency, isolation, and durability each protect a different failure class.\\n- Put durable invariants in constraints where you can; isolation and application logic must cover the rest.\\n- Isolation level names are not portable across engines — verify what anomalies your database actually prevents.\\n- Durability is configuration-dependent: a commit acknowledgement only survives the failures your fsync and replication settings promise.\\n- Prefer shorter transactions, correct constraints, and deliberate isolation over weakening commit durability for speculative throughput gains.\\n","sourceMigration":{"sourceIds":["src-acid-properties-in-sql-databases"],"sourceVersion":"v1.4.0","sourceUrl":"https://abstractalgorithms.dev/acid-properties-in-sql-databases","reviewState":"pending-review","coverage":[{"id":"acid-guarantees-and-transfer","sourceHeadings":["The $500 That Vanished: Why ACID Properties Exist","ACID Is Four Guarantees, Not One Feature"],"destinationHeading":"A transfer is one decision, even when the database performs many writes","disposition":"transformed"},{"id":"atomicity-and-logs","sourceHeadings":["Atomicity: How WAL and Undo Logs Guarantee All-or-Nothing","The WAL Internals: LSNs, WAL Segments, and the Commit Pipeline"],"destinationHeading":"Stage 1 — Atomicity: make the transfer all-or-nothing","disposition":"transformed"},{"id":"consistency-and-constraints","sourceHeadings":["Consistency: How Constraints Keep the Database in a Legal State","The critical distinction: ACID Consistency ≠ CAP Consistency"],"destinationHeading":"Stage 2 — Consistency: preserve invariants at transaction boundaries","disposition":"transformed"},{"id":"isolation-and-anomalies","sourceHeadings":["Isolation: How MVCC and Locking Prevent Concurrent Transactions from Interfering","Serializable Snapshot Isolation (SSI) in PostgreSQL","Database isolation defaults"],"destinationHeading":"Stage 3 — Isolation: define what concurrent transactions can observe","disposition":"transformed"},{"id":"durability-and-recovery","sourceHeadings":["Durability: How WAL and fsync Guarantee Committed Data Survives Crashes","How PostgreSQL implements Durability — WAL + fsync","How MySQL InnoDB implements Durability — Redo Log"],"destinationHeading":"Stage 4 — Durability: make an acknowledged commit survive the failures you promise to handle","disposition":"transformed"},{"id":"performance-and-configuration","sourceHeadings":["Performance Analysis: The fsync Bottleneck and Group Commit","Durability vs. Throughput: The fsync Trade-off","PostgreSQL and MySQL: Production ACID Configuration"],"destinationHeading":"Choosing isolation and durability deliberately","disposition":"transformed"},{"id":"tradeoffs-misconceptions-and-limits","sourceHeadings":["ACID vs. BASE: When Full Guarantees Are Too Expensive to Distribute","Common Misconceptions About ACID That Lead to Production Bugs","Lessons Learned from Production ACID Failures and Near-Misses"],"destinationHeading":"What this scenario does not guarantee","disposition":"transformed"},{"id":"engine-comparison-details","sourceHeadings":["How PostgreSQL, MySQL, Oracle, and SQL Server Implement Each Property"],"disposition":"pending","rationale":"The current rewrite explains PostgreSQL and InnoDB mechanisms but does not yet preserve the source comparison across all four engines."},{"id":"operational-setting-examples","sourceHeadings":["PostgreSQL postgresql.conf — Durability and WAL settings","MySQL my.cnf — InnoDB Durability settings","Choosing the Right Isolation Level and Durability Setting for Your Workload"],"disposition":"pending","rationale":"Detailed configuration tables and setting examples require source-by-source review before they can be considered migrated."},{"id":"source-code-and-diagram-inventory","sourceHeadings":["All fenced code examples and legacy diagram blocks"],"disposition":"pending","rationale":"The v2 narrative includes new illustrative SQL and diagrams; individual legacy code and diagram blocks have not yet been reconciled."},{"id":"key-learnings","sourceHeadings":["Summary & Key Takeaways","Lessons Learned","Closing guidance"],"destinationHeading":"Key learnings","disposition":"transformed","rationale":"Closing learnings section added so the learner narrative ends with explicit takeaways."}]},"reviewStatus":"ai-candidate","tags":["databases","postgresql","acid","wal","mvcc","transactions"]},{"id":"article-bloom-filters-explained","slug":"bloom-filters-explained","title":"Bloom Filters Explained: Membership Testing with Zero False Negatives","subtitle":"A username availability scenario using compact probabilistic membership tests before the database","summary":"Follow a registration API that uses a Bloom filter to reject unknown usernames in memory, preserve zero false negatives, and route only uncertain cases to authoritative storage.","author":{"name":"Abstract Algorithms Data Structures Team","avatarUrl":"/images/authors/team.png"},"publishedAt":"2026-10-07T00:00:00Z","updatedAt":"2026-10-07T00:00:00Z","linkedConceptSlugs":["hash-tables-and-bloom-filters","caching","database-indexing","load-balancing"],"useCase":{"goal":"Answer username availability checks in sub-millisecond time without storing every username on every app server.","actorsAndComponents":["Web client","Username API","In-memory Bloom filter","Accounts database"],"requirements":["Zero false negatives: a name never inserted must never be reported as taken solely because of the filter.","Bounded memory: store bits, not full username strings.","Explicit false-positive budget that operators can monitor."],"constraints":["Billions of historical usernames cannot fit in per-node hash tables.","Database lookups on every keystroke are too slow."],"assumptions":["Illustrative teaching scenario rebuilt from the legacy bloom-filters-explained source."]},"stages":[{"stageNumber":1,"title":"Stage 1 — Size the filter for corpus and false-positive budget","decisionOrAction":"Operators choose bit-array size and hash-function count before serving traffic.","linkedConceptSlugs":["hash-tables-and-bloom-filters"],"conceptRoles":[{"conceptSlug":"hash-tables-and-bloom-filters","roleDescription":"Defines the probabilistic set semantics and sizing trade-offs for the filter."}],"componentBehavior":"Provisioning sets m, k, and memory limits from expected element count and target FPR.","observableOutput":"A published false-positive budget and memory footprint for the edge tier."},{"stageNumber":2,"title":"Stage 2 — Insert and lookup on the hot path","decisionOrAction":"API sets k bits on insert and checks the same k bits on lookup.","linkedConceptSlugs":["caching"],"conceptRoles":[{"conceptSlug":"caching","roleDescription":"Places the filter in front of slower authoritative storage."}],"componentBehavior":"Negative lookups return immediately when any bit is zero.","observableOutput":"Most availability checks never reach the database."},{"stageNumber":3,"title":"Stage 3 — Handle false positives without breaking correctness","decisionOrAction":"Treat “maybe present” as uncertainty and confirm against the database.","linkedConceptSlugs":["database-indexing"],"conceptRoles":[{"conceptSlug":"database-indexing","roleDescription":"Provides the authoritative lookup after a possible positive."}],"componentBehavior":"Database confirms or rejects registration after a filter false positive.","observableOutput":"Correctness preserved; false positives only add read cost."},{"stageNumber":4,"title":"Stage 4 — Operate the filter in production","decisionOrAction":"Replicate or centralize filter updates across edge nodes.","linkedConceptSlugs":["load-balancing"],"conceptRoles":[{"conceptSlug":"load-balancing","roleDescription":"Explains multi-node filter consistency and traffic distribution."}],"componentBehavior":"Operators monitor FPR drift and rebuild when corpus exceeds sizing assumptions.","observableOutput":"Teams can explain saved I/O and residual database reads."}],"outcome":{"endToEndResult":"Username checks stay fast while authoritative storage remains the source of truth.","observedUserBehavior":"Users see quick availability feedback during registration.","observedOperatorBehavior":"Operators track false-positive rate and filter memory against plan.","keyTradeoffs":["Exact hash tables provide certainty but exceed memory budget at scale."]},"alternatives":[{"title":"Exact hash table","explanation":"Stores full keys; does not fit memory budget at billions of usernames."},{"title":"Cuckoo filter","explanation":"Supports deletion with different space and implementation trade-offs."}],"failuresAndDegradedModes":[{"name":"Stale filter replica","behavior":"A node missing inserts can disagree with peers unless updates are replicated."},{"name":"Oversized corpus","behavior":"False-positive rate rises until the filter is rebuilt with a larger bit array."}],"evidenceRecord":{"isSourcedProductionClaim":true,"sourceUrlOrAttribution":"https://abstractalgorithms.dev/bloom-filters-explained","statedAssumptions":["Rebuilt v2 scenario from legacy source; pending editorial review."]},"markdownContent":"\\n## A username check must be fast before it touches the database\\n\\nA registration API receives millions of username availability checks per day. Storing every username in a hash table on every app server is too expensive, and querying the database on every keystroke is too slow. The team needs a compact pre-filter that can prove **absence** cheaply and route only uncertain cases to durable storage.\\n\\nA Bloom filter is the first gate in that path. It cannot confirm membership with certainty, but it can reject names that were never inserted. That property drives the architecture below.\\n\\n```architecture\\n{\\"view\\":\\"high-level\\",\\"title\\":\\"Username availability pre-check\\",\\"direction\\":\\"LR\\",\\"groups\\":[{\\"id\\":\\"clients\\",\\"label\\":\\"Clients\\",\\"tone\\":\\"slate\\"},{\\"id\\":\\"edge\\",\\"label\\":\\"Edge API\\",\\"tone\\":\\"green\\"},{\\"id\\":\\"bloom\\",\\"label\\":\\"Bloom filter\\",\\"tone\\":\\"blue\\"},{\\"id\\":\\"db\\",\\"label\\":\\"Account DB\\",\\"tone\\":\\"amber\\"}],\\"nodes\\":[{\\"id\\":\\"web\\",\\"label\\":\\"Web client\\",\\"component\\":\\"web-browser\\",\\"group\\":\\"clients\\"},{\\"id\\":\\"api\\",\\"label\\":\\"Username API\\",\\"component\\":\\"api-gateway\\",\\"group\\":\\"edge\\"},{\\"id\\":\\"filter\\",\\"label\\":\\"In-memory Bloom filter\\",\\"component\\":\\"redis\\",\\"group\\":\\"bloom\\"},{\\"id\\":\\"accounts\\",\\"label\\":\\"Accounts table\\",\\"component\\":\\"postgresql\\",\\"group\\":\\"db\\"}],\\"edges\\":[{\\"from\\":\\"web\\",\\"to\\":\\"api\\",\\"kind\\":\\"request\\"},{\\"from\\":\\"api\\",\\"to\\":\\"filter\\",\\"kind\\":\\"read\\"},{\\"from\\":\\"api\\",\\"to\\":\\"accounts\\",\\"kind\\":\\"fallback\\"}]}\\n```\\n\\n## Stage 1 — Size the filter for the expected corpus and false-positive budget\\n\\nBefore any insert or lookup runs, operators choose the bit-array size `m` and hash-function count `k` for the expected username count and acceptable false-positive rate. **hash-tables-and-bloom-filters** governs this sizing decision because the filter is a probabilistic set, not a dictionary of values.\\n\\n- Target roughly 10 bits per element for about 1% false-positive rate in many production calculators.\\n- More hash functions reduce false positives but increase CPU per lookup.\\n- The filter stores only bits; it never stores the username string itself.\\n\\n**Observable outcome:** The team publishes an explicit false-positive budget (for example 0.1%) and provisions memory accordingly.\\n\\n## Stage 2 — Insert and lookup on the hot path\\n\\nWhen a username is reserved, the API hashes it with `k` independent functions and sets the corresponding bits. On lookup, the API checks the same `k` positions. If any bit is zero, the name is **definitely not** in the set.\\n\\n```java\\nboolean mightContain(String username) {\\n  for (int hash : hashFunctions) {\\n    if (!bits.get(hash(username))) {\\n      return false; // definitely absent\\n    }\\n  }\\n  return true; // maybe present\\n}\\n```\\n\\n**caching** explains why this structure sits in front of slower storage: most negative answers never leave memory.\\n\\n**Observable outcome:** Callers receive an immediate “available” response when the filter proves absence; only “maybe present” results trigger a database read.\\n\\n## Stage 3 — Handle false positives without breaking correctness\\n\\nA false positive means every checked bit is one even though the username was never inserted. The API must treat that as uncertainty, not as proof of existence. **database-indexing** covers the authoritative lookup that follows.\\n\\n- False negatives are impossible: a zero bit guarantees the element was never inserted.\\n- False positives only add an extra read; they must not block legitimate registrations.\\n- Operators monitor false-positive rate against the sizing assumptions as the corpus grows.\\n\\n**Observable outcome:** Availability checks stay correct because the database remains the source of truth for positive confirmation.\\n\\n## Stage 4 — Operate the filter in production\\n\\nProduction systems place Bloom filters in front of LSM stores, CDNs, and security scanners. RedisBloom and similar modules expose the same semantics with native commands when teams do not want to ship a custom implementation.\\n\\n**load-balancing** matters when many edge nodes each hold a filter copy: replicas must receive the same inserts or share a centralized filter service.\\n\\n**Observable outcome:** Operators can explain where the filter saved I/O and where a false positive still triggered a downstream query.\\n\\n## End-to-end outcome\\n\\nThe registration path stays fast because most username checks end at the filter. Correctness is preserved because uncertain answers still consult authoritative storage. Memory stays bounded because the filter stores bits, not strings.\\n\\n## Alternatives considered\\n\\n### Exact hash table\\nProvides certainty but stores full keys and does not fit the memory budget at billions of usernames.\\n\\n### Cuckoo filter\\nSupports deletion with different space trade-offs; useful when removals are frequent.\\n\\n## Failure and degraded modes\\n\\n### Stale filter replica\\nIf one edge node misses inserts, it may report false negatives relative to other nodes unless inserts are replicated or centralized.\\n\\n### Oversized corpus\\nIf the username count exceeds the sizing plan, false-positive rate rises and database load increases until the filter is rebuilt with a larger bit array.\\n\\n## Key learnings\\n\\n- A Bloom filter is a pre-filter for absence: a clear “no” is definitive; a “maybe” still needs the authoritative store.\\n- Size the bit array and hash count for the expected corpus and target false-positive rate before you ship — late rebuilds are expensive.\\n- Never treat a Bloom positive as proof of membership in security or uniqueness-critical paths.\\n- Replicate or centralize inserts carefully; a stale replica can create false negatives relative to other nodes.\\n- When deletions matter, consider a Cuckoo filter or another structure that supports removal without rebuilding.\\n","sourceMigration":{"sourceIds":["src-bloom-filters-explained"],"sourceVersion":"v1.4.0","sourceUrl":"https://abstractalgorithms.dev/bloom-filters-explained","reviewState":"pending-review","coverage":[{"id":"membership-problem","sourceHeadings":["The Set Membership Problem at Three Billion Usernames"],"destinationHeading":"A username check must be fast before it touches the database","disposition":"transformed"},{"id":"bit-array-and-lookup","sourceHeadings":["The Bit Array Skeleton","Insert and Lookup"],"destinationHeading":"Stage 2 — Insert and lookup on the hot path","disposition":"transformed"},{"id":"sizing-math","sourceHeadings":["Deep Dive: Sizing, Math, and Performance"],"destinationHeading":"Stage 1 — Size the filter for the expected corpus and false-positive budget","disposition":"transformed"},{"id":"production-and-redisbloom","sourceHeadings":["Production Deployments","Redis RedisBloom"],"destinationHeading":"Stage 4 — Operate the filter in production","disposition":"transformed"},{"id":"tradeoffs-and-cuckoo","sourceHeadings":["Trade-offs and Failure Modes","Cuckoo Filter","Decision Guide"],"destinationHeading":"Alternatives considered","disposition":"transformed"},{"id":"java-implementation-inventory","sourceHeadings":["Implementing a Bloom Filter in Java"],"disposition":"pending","rationale":"The hand-authored rewrite includes a representative lookup snippet; the full source implementation blocks await editorial reconciliation."},{"id":"key-learnings","sourceHeadings":["Summary & Key Takeaways","Lessons Learned","Closing guidance"],"destinationHeading":"Key learnings","disposition":"transformed","rationale":"Closing learnings section added so the learner narrative ends with explicit takeaways."}]},"reviewStatus":"ai-candidate","reviewerName":"Abstract Algorithms Editorial Board","reviewedAt":"2026-10-07T00:00:00Z","tags":["bloom-filter","probabilistic","membership","caching","data-structures"]},{"id":"article-consistency-patterns-in-distributed-systems","slug":"consistency-patterns-in-distributed-systems","title":"The Consistency Continuum: From Read-Your-Own-Writes to Leaderless Replication","subtitle":"A step-by-step engineering guide to Quorum math, Monotonic Reads, and Linearizability in distributed data stores","summary":"Analyze how distributed databases balance latency, availability, and consistency guarantees across WAN networks using R+W > N Quorum math and read-repair protocols.","author":{"name":"Abstract Algorithms Distributed Systems Team","avatarUrl":"/images/authors/team.png"},"publishedAt":"2026-10-07T00:00:00Z","updatedAt":"2026-10-07T00:00:00Z","linkedConceptSlugs":["caching","distributed-locking"],"useCase":{"goal":"Guarantee read-your-own-writes consistency for user profile updates across geographically replicated Dynamo-style database nodes without global lock bottlenecks.","actorsAndComponents":["Client Mobile App","Global API Gateway (Edge Node)","Leaderless Storage Nodes (Node 1, Node 2, Node 3)","Asynchronous Read Repair Service"],"requirements":["Strict Read-Your-Own-Writes: A user must immediately see their own profile updates.","Quorum Intersection (R + W > N): Guaranteed overlap between write quorums and read quorums.","Fault Tolerance: System continues serving reads and writes if 1 of 3 nodes experiences network partition."],"constraints":["Cross-region network latency (120ms round-trip between US-East and EU-Central).","No single primary leader node available for centralized ordering."],"assumptions":["Replication factor N=3 across 3 independent availability zones.","Configured Quorum values: Write Quorum W=2, Read Quorum R=2."]},"stages":[{"stageNumber":1,"title":"Stage 1: Client Issues Write Request to Quorum Nodes (W=2)","decisionOrAction":"User updates display name. API gateway forwards write to 3 nodes in parallel with vector clock version v2.","linkedConceptSlugs":["distributed-locking"],"conceptRoles":[{"conceptSlug":"distributed-locking","roleDescription":"Coordinates version timestamps and prevents concurrent mutation conflicts."}],"componentBehavior":"Node 1 and Node 2 confirm write acknowledgment in 18ms. Node 3 fails to respond in time due to transient jitter.","observableOutput":"W=2 threshold met. HTTP 200 OK returned to client with version v2 timestamp."},{"stageNumber":2,"title":"Stage 2: Client Executes Quorum Read (R=2) & Read Repair","decisionOrAction":"User refreshes profile. Client requests value from Node 2 and Node 3 in parallel.","linkedConceptSlugs":["caching"],"conceptRoles":[{"conceptSlug":"caching","roleDescription":"Node-level memory caches serve read values alongside version headers."}],"componentBehavior":"Node 2 returns version v2 (\\"Alice\\"), Node 3 returns stale version v1 (\\"Bob\\"). Quorum engine picks v2 and triggers async background write to Node 3.","observableOutput":"Read returns correct value \\"Alice\\". Asynchronous Read Repair queued for Node 3."}],"outcome":{"endToEndResult":"Achieves strong consistency for user writes while maintaining 99.99% system availability under single-node failures.","observedUserBehavior":"Users immediately see their profile changes upon page refresh across device switches.","observedOperatorBehavior":"Operators observe stable 99.8% Quorum overlap and automatic resolution of stale node replicas.","keyTradeoffs":["Configuring W=2, R=2 ensures R+W > N consistency but increases read latency compared to local R=1 reads.","Vector clocks resolve concurrent updates accurately but add payload metadata size."]},"alternatives":[{"title":"Single Primary Leader Replication","explanation":"Eliminates conflict resolution complexity, but creates single-point-of-failure bottlenecks for cross-region writes."}],"failuresAndDegradedModes":[{"name":"Network Partition on 2 Nodes","behavior":"When 2 of 3 nodes are unreachable, W=2 writes fail with HTTP 503, preserving data correctness over availability (CP mode)."}],"evidenceRecord":{"isSourcedProductionClaim":true,"sourceUrlOrAttribution":"https://aws.amazon.com/dynamodb/","statedAssumptions":["Assumes N=3, W=2, R=2 Quorum configuration."]},"reviewStatus":"canonical","reviewerName":"Principal Distributed Systems Architect","reviewedAt":"2026-10-07T00:00:00Z","tags":["consistency","quorum","replication","dynamo","distributed-systems"],"markdownContent":"\\n## Key learnings\\n\\n- Consistency is a product choice: stronger guarantees cost latency and availability under partition; weaker models need explicit conflict handling.\\n- Name the read-after-write and cross-region expectations in the API contract so clients do not invent stronger guarantees than you provide.\\n- Prefer idempotent writes and version vectors or causal metadata when concurrent updates are normal.\\n- Tunable consistency (for example quorum reads/writes) lets you trade freshness per operation instead of per database.\\n- Test the degraded path — failover and partition behavior define the real consistency story operators will live with.\\n"},{"id":"article-consensus-algorithms-raft-paxos","slug":"consensus-algorithms-raft-paxos","title":"A Guide to Raft, Paxos, and Consensus Algorithms","subtitle":"How distributed state machines elect leaders, replicate logs, and survive split-brain network partitions","summary":"Trace how Raft consensus maintains a replicated log across a 5-node cluster, handles randomized election timeouts, and guarantees safety during network splits.","author":{"name":"Abstract Algorithms Distributed Systems Team","avatarUrl":"/images/authors/team.png"},"publishedAt":"2026-10-07T00:00:00Z","updatedAt":"2026-10-07T00:00:00Z","linkedConceptSlugs":["distributed-locking","caching"],"useCase":{"goal":"Maintain an immutable, linearizable consensus log across 5 distributed cluster nodes during network partitions.","actorsAndComponents":["Raft Leader (Node A)","Follower Nodes (Nodes B, C, D, E)","Replicated State Machine"],"requirements":["Leader Completeness: If a log entry is committed in a given term, that entry will be present in logs of leaders for all higher terms.","Election Safety: At most one leader can be elected per term.","Majority Quorum: Progress requires at least 3 of 5 active nodes."],"constraints":["Network delay variance can cause split-vote elections if timeouts are uniform."],"assumptions":["Randomized election timeouts between 150ms and 300ms."]},"stages":[{"stageNumber":1,"title":"Stage 1: Leader Election via Term Votes","decisionOrAction":"Node A heartbeat timer expires. Node A transitions to Candidate, increments Term to 4, and requests votes.","linkedConceptSlugs":["distributed-locking"],"conceptRoles":[{"conceptSlug":"distributed-locking","roleDescription":"Term votes act as exclusive distributed leadership leases."}],"componentBehavior":"Nodes B and C grant votes to Node A (first candidate seen in Term 4). Node A collects majority (3 votes).","observableOutput":"Node A elected Leader for Term 4. Begins broadcasting heartbeats."}],"outcome":{"endToEndResult":"Guarantees zero log divergence and zero split-brain execution across 5 nodes.","observedUserBehavior":"State machine updates execute with linearizable consistency.","observedOperatorBehavior":"Cluster automatically re-elects new leader in under 300ms following node crash.","keyTradeoffs":["Strict majority consensus prevents split-brain but requires 3 active nodes out of 5 to accept writes."]},"alternatives":[{"title":"Multi-Paxos","explanation":"Equivalent safety guarantees but higher implementation complexity compared to Raft decomposed state machine."}],"failuresAndDegradedModes":[{"name":"Cluster Network Partition (3 vs 2)","behavior":"Majority partition (3 nodes) continues committing log entries; minority partition (2 nodes) cannot reach quorum and rejects client writes."}],"evidenceRecord":{"isSourcedProductionClaim":true,"sourceUrlOrAttribution":"https://raft.github.io/","statedAssumptions":["5-node cluster with 150-300ms election timeout."]},"reviewStatus":"canonical","reviewerName":"Principal Distributed Systems Architect","reviewedAt":"2026-10-07T00:00:00Z","tags":["raft","paxos","consensus","leader-election","distributed-systems"],"markdownContent":"\\n## Key learnings\\n\\n- Consensus exists to agree on one order of decisions despite crashes and slow nodes, not to make every replica identically fresh at every moment.\\n- Leader-based protocols (Raft) are easier to reason about operationally; understand election, log replication, and commit index as the core loop.\\n- A majority quorum is the durability and safety boundary — minority replicas cannot safely acknowledge committed state alone.\\n- Timeouts and leader leases are availability knobs; set them for your RTT and failure detector, not from defaults copied across regions.\\n- Clients must retry with idempotency: leadership changes and reconfigurations will abort in-flight proposals.\\n"},{"id":"article-how-redis-internals-work","slug":"how-redis-internals-work","title":"Redis Single-Threaded Event Loop & Epoll: High-Throughput I/O Architecture","subtitle":"How Redis handles 100,000+ QPS without multi-threading lock contention using Linux epoll and non-blocking sockets","summary":"Trace how Redis Event Reactor multiplexes thousands of concurrent TCP client connections through a single main thread loop, avoiding thread synchronization overhead.","author":{"name":"Abstract Algorithms Database Team","avatarUrl":"/images/authors/team.png"},"publishedAt":"2026-10-07T00:00:00Z","updatedAt":"2026-10-07T00:00:00Z","linkedConceptSlugs":["caching","rate-limiting"],"useCase":{"goal":"Serve 120,000 read/write cache queries per second on a single CPU core with sub-millisecond p99 latency.","actorsAndComponents":["Client API Servers","Linux epoll Event Loop (AE Event Reactor)","Single Main Worker Thread","In-Memory Hash Table Dictionary"],"requirements":["Zero Lock Contention: Eliminates mutexes and context switches.","Non-Blocking Sockets: Read and write operations never block main loop execution.","Sub-Millisecond p99: Latency stays below 0.8ms under 80% CPU utilization."],"constraints":["Any long-running O(N) operation (e.g. KEYS *) blocks all incoming client traffic."],"assumptions":["Linux 5.x+ kernel supporting epoll_wait and edge-triggered socket notifications."]},"stages":[{"stageNumber":1,"title":"Stage 1: Epoll Event Registration & Ingress Dispatch","decisionOrAction":"Client sends GET cache:user:1001 command over TCP socket. Linux epoll_wait signals readable file descriptor.","linkedConceptSlugs":["caching"],"conceptRoles":[{"conceptSlug":"caching","roleDescription":"Maintains in-memory key-value dictionary and memory eviction policies."}],"componentBehavior":"Redis main thread wakes from epoll_wait, reads socket payload into client buffer, and parses RESP protocol.","observableOutput":"Command parsed as GET in 12 microseconds; key lookup dispatched to dictFind()."},{"stageNumber":2,"title":"Stage 2: Key Dictionary Lookup & Asynchronous Reply Buffer","decisionOrAction":"Main thread retrieves value from hash table and appends output to client write buffer.","linkedConceptSlugs":["rate-limiting"],"conceptRoles":[{"conceptSlug":"rate-limiting","roleDescription":"Calculates TTL expiration timestamps and LRU memory eviction ranks."}],"componentBehavior":"Lookup succeeds; dictFind returns value pointer. Reply string written to client outbuf.","observableOutput":"Output queued in client buffer. Epoll registers EPOLLOUT event for asynchronous socket write."}],"outcome":{"endToEndResult":"Delivers 125,000 QPS at p99 = 0.45ms on a single CPU core without thread lock overhead.","observedUserBehavior":"API clients receive cache hits in sub-millisecond round-trip times.","observedOperatorBehavior":"CPU utilization stays linear; zero context switch overhead observed in perf top.","keyTradeoffs":["Single-threaded architecture maximizes CPU cache locality but cannot scale a single Redis instance across multiple CPU cores."]},"alternatives":[{"title":"Multi-Threaded Work-Stealing Reactor (Memcached)","explanation":"Utilizes multiple CPU cores per process but requires fine-grained slab locking."}],"failuresAndDegradedModes":[{"name":"O(N) Blocking Command Execution","behavior":"Running KEYS * or DEL on a 10,000,000 element set stalls the main loop, causing client timeout cascades."}],"evidenceRecord":{"isSourcedProductionClaim":true,"sourceUrlOrAttribution":"https://redis.io/docs/latest/operate/oss_and_stack/reference/internals/internals-rediseventloop/","statedAssumptions":["Assumes Linux epoll multiplexing on Redis 7.x."]},"markdownContent":"\\n## One thread must serve thousands of cache clients without blocking\\n\\nA product API depends on Redis for session and catalog caching. At peak, tens of thousands of TCP connections send sub-millisecond GET and SET commands. Spawning a thread per connection would waste memory on stacks and context switches. Redis instead multiplexes all client I/O through a single event loop on one core.\\n\\nThis scenario follows one GET command from socket readability through dictionary lookup to asynchronous reply buffering.\\n\\n```mermaid\\nsequenceDiagram\\n    title Redis Single-Threaded Event Loop Dispatch\\n    participant Client as API client\\n    participant Loop as Redis main thread\\n    participant Epoll as Linux epoll\\n    participant Dict as In-memory dict\\n    Client->>Loop: GET cache:user:1001\\n    Loop->>Epoll: wait for readable socket\\n    Epoll-->>Loop: fd ready\\n    Loop->>Dict: dictFind(key)\\n    Dict-->>Loop: value pointer\\n    Loop-->>Client: RESP reply buffered\\n```\\n\\n## Stage 1 — Register sockets and wake on readability\\n\\nWhen a client connects, Redis registers the socket with **epoll** in non-blocking mode. The main thread blocks in `epoll_wait` until at least one descriptor is ready. **caching** is the storage model this loop serves: every ready event eventually becomes a key lookup or mutation.\\n\\n- No thread is dedicated to a single client; readiness drives scheduling.\\n- Edge-triggered or level-triggered epoll behavior must match the read loop implementation.\\n- Slow clients cannot block others because sockets are non-blocking.\\n\\n**Observable outcome:** The process wakes only when work exists, keeping CPU focused on protocol parsing and command dispatch.\\n\\n## Stage 2 — Parse RESP and dispatch the command\\n\\nThe main thread reads available bytes, parses the Redis Serialization Protocol (RESP), and maps the command to a handler. For `GET cache:user:1001`, the handler performs a dictionary lookup and prepares the reply in the client output buffer.\\n\\n**rate-limiting** appears indirectly through TTL and eviction policies that decide whether a key is still valid when the lookup succeeds.\\n\\n**Observable outcome:** The command is parsed and executed without yielding the main thread to another client mid-command.\\n\\n## Stage 3 — Buffer replies and register writable events\\n\\nIf the kernel send buffer is full, Redis queues the response and registers a writable epoll event. The same thread later drains the output buffer when the socket accepts more data.\\n\\n**Observable outcome:** Clients receive responses with predictable latency until a blocking command stalls the loop.\\n\\n## End-to-end outcome\\n\\nRedis sustains very high QPS on one core because it avoids lock contention and schedules by I/O readiness. Operators trade horizontal sharding for per-instance throughput when a single hot key or blocking command appears.\\n\\n## Alternatives considered\\n\\n### Multi-threaded cache (Memcached-style)\\nUses multiple cores per process but pays for fine-grained locking on shared structures.\\n\\n## Failure and degraded modes\\n\\n### Blocking O(N) commands\\nCommands such as `KEYS *` monopolize the main thread and stall every other client until the scan completes.\\n\\n## Key learnings\\n\\n- Redis’s single-threaded command execution model buys simplicity and low latency, but any blocking O(N) command stalls every client on that instance.\\n- The event loop multiplexes sockets; throughput comes from non-blocking I/O plus fast in-memory structures, not from one thread per connection.\\n- Persistence (RDB/AOF) and replication are separate durability/HA choices — neither is free with respect to latency or failover semantics.\\n- Hot keys and large values dominate p99 more often than raw ops/sec averages suggest; design keys and commands for that reality.\\n- Prefer bounded commands and pipelining over KEYS-style scans in production paths.\\n","sourceMigration":{"sourceIds":["src-how-redis-internals-work"],"sourceVersion":"v1.4.0","sourceUrl":"https://abstractalgorithms.dev/how-redis-internals-work","reviewState":"pending-review","coverage":[{"id":"event-loop-overview","sourceHeadings":["How It Works: Under the Hood of the Redis Single-Threaded Engine"],"destinationHeading":"One thread must serve thousands of cache clients without blocking","disposition":"transformed"},{"id":"epoll-and-read","sourceHeadings":["Event loop","epoll"],"destinationHeading":"Stage 1 — Register sockets and wake on readability","disposition":"transformed"},{"id":"blocking-commands","sourceHeadings":["Blocking commands","KEYS"],"destinationHeading":"Failure and degraded modes","disposition":"transformed"},{"id":"key-learnings","sourceHeadings":["Summary & Key Takeaways","Lessons Learned","Closing guidance"],"destinationHeading":"Key learnings","disposition":"transformed","rationale":"Closing learnings section added so the learner narrative ends with explicit takeaways."}]},"reviewStatus":"ai-candidate","reviewerName":"Abstract Algorithms Editorial Board","reviewedAt":"2026-10-07T00:00:00Z","tags":["redis","caching","epoll","event-loop","performance"]},{"id":"article-api-rate-limiting-strategies","slug":"api-rate-limiting-strategies","title":"API Gateway Rate Limiting: Token Bucket, Leaky Bucket, and Distributed Sliding Window Counters","subtitle":"Preventing API overload and DDoS attacks using Redis Lua scripts and sliding window counter algorithms","summary":"Analyze how high-volume API gateways protect downstream microservices using distributed Token Bucket and Sliding Window Log algorithms in Redis.","author":{"name":"Abstract Algorithms Security & Gateway Team","avatarUrl":"/images/authors/team.png"},"publishedAt":"2026-10-07T00:00:00Z","updatedAt":"2026-10-07T00:00:00Z","linkedConceptSlugs":["rate-limiting","caching"],"useCase":{"goal":"Enforce a strict limit of 100 requests per minute per API key across 10 distributed gateway nodes without race conditions.","actorsAndComponents":["Client Application (API Consumer)","API Gateway Edge Nodes","Centralized Redis Cluster (Lua Engine)","Downstream Microservices (Protected Resource)"],"requirements":["Atomicity: Rate limit checks and token deductions must occur atomically.","Sub-Millisecond Overhead: Rate limit evaluation adds < 2ms latency per request.","Graceful Degradation: If Redis fails, fall back to local in-memory token bucket."],"constraints":["Cross-node race conditions under 10,000 concurrent requests per second."],"assumptions":["Redis cluster running atomic Lua scripts for sliding window evaluation."]},"stages":[{"stageNumber":1,"title":"Stage 1: Gateway Ingress & Redis Lua Token Evaluation","decisionOrAction":"Gateway receives HTTP GET /api/v1/orders with header X-API-Key: client-8821.","linkedConceptSlugs":["rate-limiting"],"conceptRoles":[{"conceptSlug":"rate-limiting","roleDescription":"Evaluates window timestamp buckets and computes remaining quota."}],"componentBehavior":"Gateway executes atomic Lua script on Redis cluster evaluating ZREMRANGEBYSCORE and ZCARD in a single round-trip.","observableOutput":"Lua script returns quota count = 42 (limit 100). Request permitted."},{"stageNumber":2,"title":"Stage 2: Response Header Injection & Upstream Forwarding","decisionOrAction":"Gateway injects X-RateLimit-Limit: 100 and X-RateLimit-Remaining: 58 headers.","linkedConceptSlugs":["caching"],"conceptRoles":[{"conceptSlug":"caching","roleDescription":"Caches API key metadata and rate limit configurations locally."}],"componentBehavior":"Gateway forwards request to downstream order service.","observableOutput":"HTTP 200 OK returned to client with rate limit remaining telemetry headers."}],"outcome":{"endToEndResult":"Successfully throttles abusive clients while guaranteeing zero false-positive rejections for legitimate traffic.","observedUserBehavior":"Well-behaved clients execute without latency impact; exceeding clients receive HTTP 429 Too Many Requests.","observedOperatorBehavior":"Gateways maintain steady downstream backend load even during DDoS traffic surges.","keyTradeoffs":["Sliding Window Log accuracy requires storing timestamps in Redis Sorted Sets, increasing memory footprint compared to Fixed Window counters."]},"alternatives":[{"title":"Fixed Window Counter","explanation":"Lowest memory usage but allows 2x burst spikes at window boundary boundaries."}],"failuresAndDegradedModes":[{"name":"Redis Cluster Outage","behavior":"Gateways fall back to local Guava in-memory rate limiting, prioritizing availability over strict global precision."}],"evidenceRecord":{"isSourcedProductionClaim":true,"sourceUrlOrAttribution":"https://redis.io/commands/eval/","statedAssumptions":["Assumes Redis Lua script evaluation for sliding window atomic checks."]},"reviewStatus":"canonical","reviewerName":"Principal Security Architect","reviewedAt":"2026-10-07T00:00:00Z","tags":["rate-limiting","api-gateway","redis","security","sliding-window"],"markdownContent":"\\n## Key learnings\\n\\n- Rate limits are a product and fairness control, not only an abuse filter — choose token bucket, fixed window, or sliding window for the abuse pattern you face.\\n- Enforce limits at a consistent gateway or shared store; per-instance memory counters diverge under horizontal scale.\\n- Return clear quota signals (status, headers, retry guidance) so well-behaved clients back off instead of retrying blindly.\\n- Different identities need different budgets: anonymous IP, authenticated user, and partner API key rarely share one global ceiling.\\n- Load-test the limiter itself; a centralized counter can become the bottleneck you invented to protect the API.\\n"},{"id":"article-how-kafka-works","slug":"how-kafka-works","title":"Kafka Event Streaming Architecture: Consumer Groups, Partition Offsets, and Exactly-Once Semantics","subtitle":"Designing fault-tolerant high-throughput event pipelines with transactional producers and partition rebalancing","summary":"Trace how Apache Kafka partitions topics across broker clusters, manages consumer group offsets, and guarantees exactly-once processing semantics.","author":{"name":"Abstract Algorithms Data Platform Team","avatarUrl":"/images/authors/team.png"},"publishedAt":"2026-10-07T00:00:00Z","updatedAt":"2026-10-07T00:00:00Z","linkedConceptSlugs":["event-driven-architecture","consistency-replication","distributed-locking"],"useCase":{"goal":"Ingest 500,000 order event messages per second into Kafka topic order-events with ordered partition guarantees.","actorsAndComponents":["Order Service Producer","Kafka Broker Cluster (Leader & Follower Partitions)","Consumer Group (Payment & Inventory Workers)","Transactional Coordinator Engine"],"requirements":["Partition Key Ordering: All events for order_id = 9918 map to the same partition.","At-Least-Once Delivery: Consumer offsets committed to __consumer_offsets topic after processing.","Rebalance Resilience: Minimal consumer group interruption during worker node scaling."],"constraints":["Uneven partition key distribution can create hot partition bottlenecks."],"assumptions":["Kafka topic configured with replication factor = 3 and min.insync.replicas = 2."]},"stages":[{"stageNumber":1,"title":"Stage 1: Producer Key Hashing & Broker Partition Record Accumulation","decisionOrAction":"Producer computes murmur2(order_id) to select Partition 2. Batch accumulates in RecordAccumulator.","linkedConceptSlugs":["event-driven-architecture"],"conceptRoles":[{"conceptSlug":"event-driven-architecture","roleDescription":"The topic is the durable contract between order, payment, and inventory services."}],"componentBehavior":"Producer sends ProduceRequest to Partition 2 Leader Broker. Broker appends payload to segment log.","observableOutput":"Broker returns ProduceResponse with offset 481902; followers fetch log segment."},{"stageNumber":2,"title":"Stage 2: Consumer Fetching & Cooperative Offset Commit","decisionOrAction":"Consumer 1 fetches batch from Partition 2 Leader and processes payment confirmation.","linkedConceptSlugs":["distributed-locking"],"conceptRoles":[{"conceptSlug":"distributed-locking","roleDescription":"Partition leases guarantee single consumer execution per partition."}],"componentBehavior":"Payment processes successfully. Consumer commits offset 481902 to __consumer_offsets.","observableOutput":"Offset 481902 committed. Consumer consumer-group-1 lag remains 0."}],"outcome":{"endToEndResult":"Processes 500,000 msg/sec with guaranteed per-order sequence preservation and 0 message loss.","observedUserBehavior":"Order processing pipelines complete asynchronously within 50ms of user checkout.","observedOperatorBehavior":"Operators observe stable consumer group lag and balanced CPU load across 3 brokers.","keyTradeoffs":["Setting acks=all guarantees zero message loss but increases producer write latency by requiring ISR quorum acknowledgments."]},"alternatives":[{"title":"RabbitMQ AMQP Queues","explanation":"Provides flexible routing keys but lacks immutable replayable log storage."}],"failuresAndDegradedModes":[{"name":"Consumer Worker GC Pause","behavior":"If a consumer exceeds max.poll.interval.ms, group coordinator triggers rebalance and reassigns partitions."}],"evidenceRecord":{"isSourcedProductionClaim":true,"sourceUrlOrAttribution":"https://kafka.apache.org/documentation/","statedAssumptions":["Assumes Kafka 3.x with KRaft consensus or ZooKeeper metadata."]},"markdownContent":"\\n## Order events must stay ordered per customer without losing messages on failure\\n\\nAn e-commerce platform emits `order.created`, `payment.captured`, and `inventory.reserved` events. Payment and inventory services must observe those events in a predictable order for a given order ID, survive broker restarts, and scale consumers horizontally. Kafka provides the log, partitions, and consumer groups that make that possible.\\n\\nThis scenario traces one order event from producer batching through broker append to consumer offset commit.\\n\\n```mermaid\\nsequenceDiagram\\n    title Kafka Partition Replication & Offset Commit Lifecycle\\n    participant Producer as Order service\\n    participant Broker as Partition leader\\n    participant Follower as Follower replica\\n    participant Consumer as Payment worker\\n    Producer->>Broker: Produce batch (key=order_id)\\n    Broker->>Follower: replicate segment\\n    Broker-->>Producer: offset acknowledged\\n    Consumer->>Broker: fetch from partition\\n    Consumer->>Consumer: process payment\\n    Consumer->>Broker: commit offset\\n```\\n\\n## Stage 1 — Choose the partition key and batch records\\n\\nThe producer hashes `order_id` so every event for the same order lands in one partition. That preserves order for a single key while allowing parallel partitions across the topic. **event-driven-architecture** frames the topic as the durable contract between services.\\n\\n- Partition key selection is a correctness decision, not only a throughput knob.\\n- Batching in the producer accumulator amortizes network round trips.\\n- Hot keys can create partition hotspots if skew is ignored.\\n\\n**Observable outcome:** Events for one order remain ordered within a partition.\\n\\n## Stage 2 — Replicate and acknowledge writes\\n\\nThe partition leader appends records to its log segment and waits for in-sync replicas according to `acks` and `min.insync.replicas`. **consistency-replication** explains why operators tune these settings against their durability promise.\\n\\n**Observable outcome:** Producers receive an offset only after the configured replication guarantee is met.\\n\\n## Stage 3 — Consume, process, and commit offsets\\n\\nConsumers in the same group divide partitions among members. After processing a batch, a consumer commits its offset to `__consumer_offsets`. **distributed-locking** analogies apply during rebalance: only one active consumer owns a partition assignment at a time.\\n\\n**Observable outcome:** Restarted consumers resume from the last committed offset; duplicate processing is possible unless idempotent handlers are used.\\n\\n## End-to-end outcome\\n\\nDownstream services scale independently while the log retains a replayable history. Operators monitor consumer lag, rebalance storms, and hot partitions.\\n\\n## Alternatives considered\\n\\n### RabbitMQ queues\\nFlexible routing but no built-in replayable partitioned log for the same retention semantics.\\n\\n## Failure and degraded modes\\n\\n### Consumer rebalance during deploy\\nPartition reassignment pauses consumption briefly; cooperative protocols reduce stop-the-world impact.\\n\\n### Hot partition\\nA skewed key distribution overloads one broker while others stay idle.\\n\\n## Key learnings\\n\\n- Kafka’s unit of scale and ordering is the partition: keying strategy determines both parallelism and hot-spot risk.\\n- Consumers advance offsets; at-least-once delivery is the default mental model unless you build stronger idempotency or transactional consume/produce.\\n- Replication and the ISR define durability — tune acks and min ISR to the loss you can accept on broker failure.\\n- Rebalances pause work; cooperative assignment and sticky membership reduce deploy-time disruption.\\n- Retention turns the log into a replayable system of record; design compaction and consumer lag alerts around that property.\\n","sourceMigration":{"sourceIds":["src-how-kafka-works"],"sourceVersion":"v1.4.0","sourceUrl":"https://abstractalgorithms.dev/how-kafka-works","reviewState":"pending-review","coverage":[{"id":"producer-partitioning","sourceHeadings":["Producer","partition key","How Kafka Works"],"destinationHeading":"Stage 1 — Choose the partition key and batch records","disposition":"transformed"},{"id":"replication","sourceHeadings":["replication","acks","min.insync.replicas"],"destinationHeading":"Stage 2 — Replicate and acknowledge writes","disposition":"transformed"},{"id":"consumer-groups","sourceHeadings":["consumer group","offset commit"],"destinationHeading":"Stage 3 — Consume, process, and commit offsets","disposition":"transformed"},{"id":"key-learnings","sourceHeadings":["Summary & Key Takeaways","Lessons Learned","Closing guidance"],"destinationHeading":"Key learnings","disposition":"transformed","rationale":"Closing learnings section added so the learner narrative ends with explicit takeaways."}]},"reviewStatus":"ai-candidate","reviewerName":"Abstract Algorithms Editorial Board","reviewedAt":"2026-10-07T00:00:00Z","tags":["kafka","event-driven","streaming","distributed-systems","messaging"]},{"id":"article-how-ai-coding-agents-work","slug":"how-ai-coding-agents-work","title":"How AI Coding Agents Work: Models, Context, Sessions, and Memory","subtitle":"Inside Claude Code, GitHub Copilot, and Cursor: how agents use LLMs, manage context windows, handle sessions, and tier memory","summary":"Follow a payment refactor that fails when the context window overflows, then trace how stateless models, ReAct loops, RAG retrieval, session replay, and four memory tiers produce every hallucination and forgotten constraint.","author":{"name":"Abstract Algorithms AI Systems Team","avatarUrl":"/images/authors/team.png"},"publishedAt":"2026-04-10T00:00:00Z","updatedAt":"2026-07-26T19:30:26.909Z","linkedConceptSlugs":["llm-agents-and-langgraph","llm-prompt-engineering","vector-embeddings-and-similarity"],"useCase":{"goal":"Complete a multi-file payment refactor without the agent forgetting interface contracts when the context window fills.","actorsAndComponents":["Developer (human supervisor)","Orchestrator and context builder","LLM API (stateless)","Tool registry (read, edit, search, terminal)","Session cache and vector store"],"requirements":["Preserve PaymentProcessor and Retryable constraints across a 45+ minute session.","Retrieve only relevant source files without exceeding the token budget.","Recover from test failures through tool observation loops."],"constraints":["128K–200K token context windows fill quickly with history, system prompt, and file content.","Each API call is stateless; the orchestrator must replay session state.","Tool results consume context and may be truncated."],"assumptions":["Illustrative teaching scenario rebuilt from the legacy how-ai-coding-agents-work source."]},"stages":[{"stageNumber":1,"title":"Stage 1 — Separate the language model from the coding agent","decisionOrAction":"Identify the three agent layers — tools, orchestration, context management — on top of a stateless LLM.","linkedConceptSlugs":["llm-agents-and-langgraph"],"conceptRoles":[{"conceptSlug":"llm-agents-and-langgraph","roleDescription":"Defines the agent loop and tool-use pattern that turns a text model into a coding agent."}],"componentBehavior":"Orchestrator registers tools, runs the ReAct loop, and assembles prompts per call.","observableOutput":"Learner can name agent layers and distinguish product differences (RAG vs large window vs sandbox)."},{"stageNumber":2,"title":"Stage 2 — Budget every turn in tokens, not words","decisionOrAction":"Treat tokens, context window size, and statelessness as the root cause of forgotten constraints.","linkedConceptSlugs":["llm-prompt-engineering"],"conceptRoles":[{"conceptSlug":"llm-prompt-engineering","roleDescription":"Explains deliberate prompt assembly and what the model can attend to per call."}],"componentBehavior":"Orchestrator serializes prior turns into each new request until truncation evicts them.","observableOutput":"Learner explains why overflow is eviction, not model failure."},{"stageNumber":3,"title":"Stage 3 — Run the ReAct loop until the task is done","decisionOrAction":"Trace Reason → Act → Observe cycles for a realistic code edit with multiple tool calls.","linkedConceptSlugs":["llm-agents-and-langgraph"],"conceptRoles":[{"conceptSlug":"llm-agents-and-langgraph","roleDescription":"Governs multi-step tool iteration until the task completes or hits iteration limits."}],"componentBehavior":"Each tool call triggers a new LLM request with injected observations.","observableOutput":"Learner counts API calls required for a read → search → edit → test flow."},{"stageNumber":4,"title":"Stage 4 — Shape what the model sees on each API call","decisionOrAction":"Allocate system prompt, history, tool schemas, and user message within the token budget.","linkedConceptSlugs":["llm-prompt-engineering"],"conceptRoles":[{"conceptSlug":"llm-prompt-engineering","roleDescription":"Covers system prompt design, tool schema cost, and streaming for tool detection."}],"componentBehavior":"Fixed system prompt cost (2K–4K tokens) loads before every user message.","observableOutput":"Learner lists API request sections and estimates fixed overhead."},{"stageNumber":5,"title":"Stage 5 — Fit a large codebase into a finite window","decisionOrAction":"Use RAG retrieval, overflow strategies, and positional attention to assemble context.","linkedConceptSlugs":["vector-embeddings-and-similarity"],"conceptRoles":[{"conceptSlug":"vector-embeddings-and-similarity","roleDescription":"Powers semantic codebase retrieval instead of loading entire repositories."}],"componentBehavior":"Context builder embeds query, retrieves top-k chunks, and evicts or summarizes on overflow.","observableOutput":"Learner describes RAG pipeline and names the overflow strategy behind a forgotten rule."},{"stageNumber":6,"title":"Stage 6 — Persist session state the model will never hold","decisionOrAction":"Serialize conversation history and replay it on each call; summarize before hard truncation.","linkedConceptSlugs":["llm-agents-and-langgraph"],"conceptRoles":[{"conceptSlug":"llm-agents-and-langgraph","roleDescription":"Session is agent-side state; sub-agents share summaries through external caches."}],"componentBehavior":"Session cache grows until history dominates the budget or expires.","observableOutput":"Learner distinguishes session replay from model memory."},{"stageNumber":7,"title":"Stage 7 — Navigate four memory tiers and tool output limits","decisionOrAction":"Map symptoms to in-context, session, vector, and parametric memory; cap verbose tool output.","linkedConceptSlugs":["vector-embeddings-and-similarity"],"conceptRoles":[{"conceptSlug":"vector-embeddings-and-similarity","roleDescription":"Tier-3 vector store supplies retrieved code; tier-4 weights fill gaps when retrieval misses."}],"componentBehavior":"Tool results truncate or summarize to prevent single-turn context bloat.","observableOutput":"Learner maps hallucination and stale-edit symptoms to the responsible tier."}],"outcome":{"endToEndResult":"Durable constraints belong in the system prompt; long sessions require RAG, summarization, or shorter scope to avoid silent truncation.","observedUserBehavior":"Developers place critical rules in .cursorrules and restart focused sessions instead of blaming model quality.","observedOperatorBehavior":"Teams monitor token budget consumption, tool-loop limits, and retrieval quality for agent deployments.","keyTradeoffs":["RAG saves tens of thousands of tokens per call but can miss files and invite parametric hallucination.","Summarization preserves session thread at 3–8s extra latency per overflow event.","Large context windows reduce retrieval need but increase cost and still suffer lost-in-the-middle effects."]},"alternatives":[{"title":"Load full repository (long context only)","explanation":"Simple for small repos; fails for monorepos and still suffers positional attention decay in the middle."},{"title":"RAG-first retrieval","explanation":"Scales to large codebases; adds retrieval latency and depends on embedding quality."},{"title":"Summarization plus rules file","explanation":"Best for long refactors if durable constraints live outside summarized history."},{"title":"Single-shot completion","explanation":"Faster for explanations; inappropriate when tool observation cycles are required."}],"failuresAndDegradedModes":[{"name":"Context overflow (silent truncation)","behavior":"Early constraints evicted without warning; mitigated by system-prompt rules and shorter sessions."},{"name":"Hallucinated paths and APIs","behavior":"Retrieval miss plus parametric fill; mitigated by linter feedback and re-read before edit."},{"name":"Infinite tool loops","behavior":"Orchestrator hits max-iteration guard; mitigated by explicit stop conditions in system prompt."},{"name":"Stale file snapshot","behavior":"Edit applies to outdated read; mitigated by hash check or automatic re-read before edit."}],"evidenceRecord":{"isSourcedProductionClaim":true,"sourceUrlOrAttribution":"https://abstractalgorithms.dev/how-ai-coding-agents-work","statedAssumptions":["Rebuilt v2 scenario from legacy source; pending editorial review."]},"markdownContent":"\\n## A refactor forgets your rules when the context window overflows\\n\\nYou are 45 minutes into a payment refactor with an AI coding agent. You established the ground rules: use the `PaymentProcessor` interface, never call `LegacyBillingClient`, and make every new service implement `Retryable`. The agent acknowledged this, generated `StripePaymentProcessor`, and started `PayPalPaymentProcessor`.\\n\\nThen the context window filled up.\\n\\nThe next response imports `LegacyBillingClient` — the class you forbade — and ignores `Retryable` entirely. The agent did not get worse. It literally never saw your earlier instructions. Those tokens were evicted when the window overflowed.\\n\\nThat failure is architectural, not accidental. Every coding agent is a stateless model plus an orchestration layer that rebuilds context on every API call. The sections below follow one realistic task from user message through tool calls, context assembly, and session limits so you can predict — and mitigate — behaviors like the one above.\\n\\n## Stage 1 — Separate the language model from the coding agent\\n\\nA plain LLM such as GPT-4o or Claude 3.5 Sonnet is a stateless text transformer: tokens in, tokens out. It cannot read your repository, run tests, or remember what you said three turns ago unless the orchestrator puts that information back into the prompt.\\n\\nAn **AI coding agent** adds three layers on top of the model:\\n\\n1. **Tool registry** — `read_file`, `edit_file`, `run_command`, `search_codebase`, and similar actions the model can request but never execute directly.\\n2. **Orchestration loop** — logic that parses model output, runs tools, injects results, and repeats until the task is complete.\\n3. **Context manager** — code that decides which files, history, and instructions fit inside the finite token window for each call.\\n\\n**llm-agents-and-langgraph** covers the orchestration pattern: the model plans, the runtime acts, observations return to context, and the loop continues.\\n\\nCopilot, Cursor, Claude Code, Aider, and Devin differ mainly in how aggressively they use RAG, how large a context window they load, and how deep their tool registries go — not in whether the underlying model is stateless.\\n\\n| Agent | Context strategy | Tool depth | Session persistence |\\n| --- | --- | --- | --- |\\n| Copilot | Editor-scoped, short history | Code search | Local JSON cache |\\n| Cursor | RAG-first on every request | File read/write + search | Local vector index |\\n| Claude Code | Large window, aggressive file load | Terminal-native tools | In-session replay |\\n| Aider | Git-native, explicit file pick | Git + terminal | `.aider.chat.history.md` |\\n| Devin | Sandboxed VM, hierarchical summary | Browser + tests + terminal | Cloud session store |\\n\\n``\\n    Dev[\\"Developer / User Prompt\\"] --> Orch[\\"Orchestration Loop (ReAct / Event Loop)\\"]\\n    subgraph AgentRuntime [\\"Agent Runtime Architecture\\"]\\n        Orch <--> Tools[\\"Tool Registry (read_file, edit_file, terminal, search)\\"]\\n        Orch <--> Ctx[\\"Context Manager (Window Budgeting & RAG Retrieval)\\"]\\n    end\\n    Orch <--> Model[\\"Stateless Foundation LLM (Claude 3.5 Sonnet / GPT-4o)\\"]\\n```\\n\\n**Observable outcome:** You can name the three agent layers and explain why swapping models does not change statelessness.\\n\\n## Stage 2 — Budget every turn in tokens, not words\\n\\nThree facts explain most confusing agent behavior:\\n\\n- **Tokens** are the billing and limit unit. Roughly 1,000 tokens ≈ 750 English words ≈ 50–80 lines of code.\\n- **Context window** is everything the model can attend to in one call. Content outside it does not exist to the model.\\n- **Statelessness** means each API call is independent. Follow-up messages are new requests that include serialized prior turns.\\n\\nWhen you send turn 20 of a refactor, the orchestrator is not \\"continuing a chat.\\" It is constructing a fresh prompt that happens to contain the text of earlier turns — until truncation removes them.\\n\\n**llm-prompt-engineering** applies here because prompt assembly is deliberate engineering: what you include, omit, and prioritize directly changes output quality.\\n\\n``\\n    UserMsg[\\"User sends message\\"] --> Orchestrator[\\"Orchestrator receives message\\"]\\n    Orchestrator --> LoadCache[\\"Load prior turns from session cache\\"]\\n    LoadCache --> RAGQuery[\\"Query vector store for relevant source files\\"]\\n    RAGQuery --> Assemble[\\"Assemble context window from prompt, history, and files\\"]\\n    Assemble --> WindowCheck{\\"Context fits in token window?\\"}\\n    WindowCheck -->|Yes| CallLLM[\\"Send complete context to LLM API as new stateless request\\"]\\n    WindowCheck -->|No| Evict[\\"Evict or summarize oldest conversation turns\\"]\\n    Evict --> CallLLM\\n    CallLLM --> Parse[\\"Parse LLM response\\"]\\n    Parse -->|Tool call detected| RunTool[\\"Execute tool and capture result\\"]\\n    RunTool --> Inject[\\"Inject tool_result message into context\\"]\\n    Inject --> CallLLM\\n    Parse -->|Final answer| Respond[\\"Return answer to user\\"]\\n    Respond --> PersistTurn[\\"Persist turn to session cache for next request\\"]\\n```\\n\\n**Observable outcome:** You can explain why a forgotten constraint is almost always a context eviction event, not model degradation.\\n\\n## Stage 3 — Run the ReAct loop until the task is done\\n\\nNon-trivial coding tasks use a **Reason → Act → Observe** loop. A single user request often triggers several LLM calls before a final answer.\\n\\n``\\n    Start([Task received]) --> Reason[Reason about current state]\\n    Reason --> Decide{Tool call needed?}\\n    Decide -->|Yes| Pick[Select tool and arguments]\\n    Pick --> Exec[Execute tool]\\n    Exec --> Observe[Observe tool result]\\n    Observe --> Inject[Inject result into context]\\n    Inject --> Reason\\n    Decide -->|No| Generate[Generate final response]\\n    Generate --> Done([Return to user])\\n```\\n\\nExample: \\"Add retry logic to `uploadFile`.\\"\\n\\n1. **Reason:** Need the current `uploadFile` implementation → **Act:** `read_file(\\"src/storage/FileUploader.java\\")`.\\n2. **Observe:** File content enters context.\\n3. **Reason:** Check whether `RetryPolicy` already exists → **Act:** `search_codebase(\\"RetryPolicy\\")`.\\n4. **Observe:** `RetryPolicy.java` found in `src/core/`.\\n5. **Generate:** Emit the diff.\\n\\nA realistic pagination task — \\"Add cursor-based pagination to `GET /users`\\" — often needs four LLM calls: assemble context, read repository file, apply edit, run tests, observe failure, fix DTO annotation, rerun tests. The agent is not one generation; it is a chain of stateless calls with growing context.\\n\\n**Observable outcome:** You can trace one user request through multiple tool round-trips and name what each observation adds to context.\\n\\n## Stage 4 — Shape what the model sees on each API call\\n\\nEvery agent-to-LLM request shares the same skeleton:\\n\\n```plaintext\\nsystem:    [repository context, style guide, tool schemas, agent persona]\\nmessages:  [conversation history — user and assistant turns]\\ntools:     [JSON schema of available tools]\\nuser:      [current user message]\\n```\\n\\nThe **system prompt** is fixed cost paid on every call. In Cursor it typically includes `.cursorrules`, open files, tool schemas, and style constraints — often **2,000–4,000 tokens** before the user speaks.\\n\\nModern APIs expose tools as JSON schemas. The model emits structured `tool_use` blocks; the orchestrator executes them and returns `tool_result` messages. The model never touches the filesystem directly.\\n\\n```json\\n{\\n  \\"name\\": \\"read_file\\",\\n  \\"description\\": \\"Read the contents of a file at the given path\\",\\n  \\"input_schema\\": {\\n    \\"type\\": \\"object\\",\\n    \\"properties\\": {\\n      \\"path\\": {\\n        \\"type\\": \\"string\\",\\n        \\"description\\": \\"Relative path from the repository root\\"\\n      }\\n    },\\n    \\"required\\": [\\"path\\"]\\n  }\\n}\\n```\\n\\nAgents stream tokens so the UI shows progress and the orchestrator can detect a tool-call block mid-stream, stop generation, execute the tool, and re-prompt — instead of waiting for a complete response.\\n\\n**Observable outcome:** You can list what sits in `system`, `messages`, and `tools`, and explain why tool schemas consume context budget.\\n\\n## Stage 5 — Fit a large codebase into a finite window\\n\\nContext management is the central engineering constraint. On a long refactor, history alone can consume 60,000 tokens; add a few large files and a 128K window is nearly full.\\n\\n| Content | Typical token cost |\\n| --- | --- |\\n| System prompt + tool schemas | 2,000–4,000 |\\n| `.cursorrules` / project config | 500–1,500 |\\n| Open and related files | 5,000–30,000 |\\n| Conversation history | 10,000–60,000 |\\n| Tool results | 2,000–20,000 |\\n\\nDumping the whole repository fails for any real codebase. Agents use **RAG**: embed files, store vectors locally, retrieve top-k chunks for each query, inject only relevant code. **vector-embeddings-and-similarity** explains why nearest-neighbor retrieval over embeddings beats keyword grep for \\"find code related to this task.\\"\\n\\n```mermaid\\nsequenceDiagram\\n    title Context Assembly & Tool Invocation Sequence\\n    participant U as User\\n    participant Orch as Orchestrator\\n    participant CB as Context Builder\\n    participant VS as Vector Store\\n    participant LLM as LLM API\\n    U->>Orch: Fix retry logic in uploadFile\\n    Orch->>CB: Assemble context\\n    CB->>VS: Embed query, retrieve top chunks\\n    VS-->>CB: FileUploader, RetryPolicy, HttpClient\\n    CB->>CB: Prepend system prompt and tool schemas\\n    CB->>CB: Append history up to token budget\\n    CB->>LLM: Send assembled context\\n    LLM-->>Orch: Tool call read_file\\n    Orch->>CB: Inject tool result\\n    CB->>LLM: Re-send with result\\n    LLM-->>Orch: Final edit diff\\n```\\n\\nTwo more constraints shape assembly:\\n\\n- **Lost in the middle:** models recall content at the start and end of context better than the middle. Put durable rules in the system prompt, not buried mid-history.\\n- **Overflow strategies:** hard truncation (drops old turns), summarization (extra LLM call, preserves semantics), priority eviction (drop tool output before user rules), or RAG refresh (re-select files each turn).\\n\\n**Observable outcome:** You can describe what RAG retrieves, what it cannot guarantee, and which overflow strategy likely caused a forgotten rule.\\n\\n## Stage 6 — Persist session state the model will never hold\\n\\nThe LLM has no memory. The **session** is an agent-side log serialized between turns — local JSON in Copilot, LanceDB-backed history in Cursor, markdown history in Aider.\\n\\n``\\n    Start[\\"START<br/>(Empty history)\\"] --> Active[\\"ACTIVE<br/>(State in memory)\\"]\\n    Active --> Idle[\\"IDLE<br/>(Cached to disk)\\"]\\n    Idle --> Expired[\\"EXPIRED<br/>(History cleared)\\"]\\n```\\n\\nEvery turn appends to the log, and the entire log is resent on the next call. By turn 20 the log may dominate the budget — which is why agents expose flags such as Aider\'s `--max-chat-history-tokens` to summarize before silent truncation.\\n\\nAutonomous systems like Devin add **sub-agents** with separate windows. They share state through external caches (summaries, scratchpad files), not a shared context window — multiplying orchestration surface area.\\n\\n**Observable outcome:** You can explain why \\"the agent remembered yesterday\\" means history replay, not model memory.\\n\\n## Stage 7 — Navigate four memory tiers and tool output limits\\n\\nCoding agents juggle four memory types with different speed, capacity, and persistence:\\n\\n| Tier | What it is | Lifetime | Example |\\n| --- | --- | --- | --- |\\n| 1 — In-context | Tokens in the current API call | One request | Open file + last tool result |\\n| 2 — Session cache | Serialized conversation and scratch state | Until expiry | Copilot local JSON, Redis for sub-agents |\\n| 3 — Vector store | Embedded codebase chunks | Project lifetime | Cursor LanceDB index |\\n| 4 — Parametric | Model weights from pretraining | Static until retrain | Patterns from other codebases |\\n\\nWhen RAG misses a file, the model fills gaps from tier 4 — which is why hallucinated package paths appear even with retrieval enabled.\\n\\nTool results bloat context fast. A 2,000-line test log can cost 4,000+ tokens in one turn. Production agents truncate or summarize tool output (Claude Code caps tool results around 4K tokens by default).\\n\\n**Observable outcome:** You can map a symptom — stale file edit, hallucinated import, forgotten rule — to the memory tier or budget decision behind it.\\n\\n## End-to-end outcome\\n\\nReturn to the opening refactor. The agent violated `PaymentProcessor` and `Retryable` because those constraints lived only in early conversation turns that truncation removed. Constraints that must survive a long session belong in `.cursorrules` or the system prompt — the only context guaranteed to reload every call.\\n\\nAfter working through the stages, you should be able to:\\n\\n- Trace a user request through context assembly, multiple ReAct iterations, and final output.\\n- Estimate what consumes the token budget and when eviction will occur.\\n- Place durable rules where overflow cannot erase them.\\n- Distinguish retrieval failure (missing file in RAG) from parametric hallucination (invented API).\\n\\nA focused pagination change in Cursor might cost ~14,800 tokens and ~45 seconds across four LLM calls — not because generation is slow, but because read → edit → test → fix is four separate stateless requests.\\n\\n## Alternatives considered\\n\\n### Load the full repository (long context only)\\nWorks for small repos under ~100K tokens. No retrieval overhead; the model sees everything. Fails for large monorepos.\\n\\n### RAG-first retrieval\\nRequired above ~500K tokens of code. Adds ~200–400ms per turn but saves tens of thousands of input tokens. Risk: wrong chunks retrieved → hallucination fills the gap.\\n\\n### Summarization plus durable rules file\\nBest for 30+ turn refactors. Accepts 3–8s summarization latency to preserve session thread. Must pair with `.cursorrules` so summarized history does not drop hard constraints.\\n\\n### Single-shot completion (no agent loop)\\nAppropriate for \\"explain this function.\\" Agent overhead — multiple tool calls — is wasted when no observation cycle is needed.\\n\\n| Situation | Recommended approach |\\n| --- | --- |\\n| Small repo (< 100K tokens) | Load all relevant files |\\n| Large monorepo | RAG + short focused sessions |\\n| Long refactor session | Summarization + `.cursorrules` |\\n| Multi-step bug fix with tests | Full ReAct loop |\\n\\n## Failure and degraded modes\\n\\n### Context overflow (silent truncation)\\nOldest turns drop without warning. The model does not signal loss. **Mitigation:** short sessions; put rules in system prompt.\\n\\n### Hallucinated paths and APIs\\nModel invents classes not in retrieved context. **Mitigation:** linter or compiler feedback injected as tool results; re-read before edit.\\n\\n### Infinite tool loops\\nRepeated `search_codebase` with rephrased queries. **Mitigation:** max-iteration guards (Claude Code ~10 calls per turn; Aider ~5 retries per edit).\\n\\n### Stale file snapshot\\nAgent edits from a read taken before the user manually changed the file. **Mitigation:** hash check or automatic re-read immediately before `edit_file`.\\n\\n### Cascading hallucination\\nBad path in `edit_file` → \\"file not found\\" → model creates duplicate file → drift compounds. **Mitigation:** stop on tool error; require user confirmation for new files.\\n\\n## Configuring agents for durable constraints\\n\\n`.cursorrules` prepends project rules to every system prompt — the most direct fix for the opening refactor failure:\\n\\n```plaintext\\n# .cursorrules\\nYou are working in a Spring Boot 3.x codebase.\\n\\nRules:\\n- All payment services must implement PaymentProcessor\\n- Never use LegacyBillingClient — deprecated\\n- All new services must use @Retryable(maxAttempts = 3)\\n```\\n\\nAider exposes explicit history control:\\n\\n```bash\\naider --model claude-3-5-sonnet-20241022 \\\\\\n      --context-window 150000 \\\\\\n      --max-chat-history-tokens 30000 \\\\\\n      src/payment/FileUploader.java src/core/RetryPolicy.java\\n```\\n\\nThese are integration-level controls. They do not change model weights; they change what the orchestrator reliably includes when the window is full.\\n\\n## Key learnings\\n\\n- Separate the language model from the orchestrator: tools, memory, and retries are product architecture, not model magic.\\n- Context windows are finite; durable rules belong in always-included files and retrieval, not only in early chat turns that can be dropped.\\n- Treat tool results as untrusted inputs that can be stale, partial, or wrong — verify before merging.\\n- Bound loops, file scopes, and attempt counts; unbounded agent autonomy is an availability and cost failure mode.\\n- Evaluate agents on task completion with constraints held, not on fluent explanation of what they intended to do.\\n","sourceMigration":{"sourceIds":["src-how-ai-coding-agents-work"],"sourceVersion":"2026-07-26T19:30:26.909Z","sourceUrl":"https://abstractalgorithms.dev/how-ai-coding-agents-work","reviewState":"pending-review","coverage":[{"id":"opening-refactor-scenario","sourceHeadings":["The 500-Line Refactor That Lost Its Mind"],"destinationHeading":"A refactor forgets your rules when the context window overflows","disposition":"transformed"},{"id":"agent-definition-and-players","sourceHeadings":["LLM + Tool Use + Orchestration Loop = AI Coding Agent"],"destinationHeading":"Stage 1 — Separate the language model from the coding agent","disposition":"transformed"},{"id":"tokens-statelessness","sourceHeadings":["Tokens, Turns, and Statelessness: The Baseline Every Developer Needs"],"destinationHeading":"Stage 2 — Budget every turn in tokens, not words","disposition":"transformed"},{"id":"react-architecture","sourceHeadings":["High-Level Architecture of an AI Coding Agent"],"destinationHeading":"Stage 3 — Run the ReAct loop until the task is done","disposition":"transformed"},{"id":"api-tool-streaming","sourceHeadings":["How Coding Agents Invoke LLMs: System Prompts, Tool Schemas, and Streaming"],"destinationHeading":"Stage 4 — Shape what the model sees on each API call","disposition":"transformed"},{"id":"context-rag-assembly","sourceHeadings":["Context Window Management: The Core Constraint Driving Agent Design"],"destinationHeading":"Stage 5 — Fit a large codebase into a finite window","disposition":"transformed"},{"id":"session-management","sourceHeadings":["Session Management: Keeping State Alive Between Turns"],"destinationHeading":"Stage 6 — Persist session state the model will never hold","disposition":"transformed"},{"id":"memory-tiers-tools","sourceHeadings":["Memory Architecture: The Four Tiers Every Agent Navigates"],"destinationHeading":"Stage 7 — Navigate four memory tiers and tool output limits","disposition":"transformed"},{"id":"product-comparison","sourceHeadings":["How GitHub Copilot, Cursor, Devin, and Claude Code Apply These Internals in Production"],"destinationHeading":"Stage 1 — Separate the language model from the coding agent","disposition":"transformed","rationale":"Product comparison table condensed into Stage 1 to avoid a standalone repetitive section."},{"id":"session-trace","sourceHeadings":["Tracing a Complete Agent Session: From Feature Request to Committed Edit"],"destinationHeading":"End-to-end outcome","disposition":"transformed"},{"id":"decision-guide","sourceHeadings":["Choosing Between Long Context, RAG, and Summarization: A Decision Guide"],"destinationHeading":"Alternatives considered","disposition":"transformed"},{"id":"failure-modes","sourceHeadings":["Failure Modes: Why Agents Hallucinate, Loop, and Forget"],"destinationHeading":"Failure and degraded modes","disposition":"transformed"},{"id":"configuration-examples","sourceHeadings":["Configuring Real Agents: Cursor Rules, Aider Flags, and OpenAI Tool Schemas"],"destinationHeading":"Configuring agents for durable constraints","disposition":"transformed"},{"id":"production-lessons","sourceHeadings":["Hard-Won Lessons from Production AI Coding Agent Deployments"],"destinationHeading":"End-to-end outcome","disposition":"transformed","rationale":"Lessons distilled into outcome bullets and failure mitigations rather than a separate numbered list."},{"id":"performance-characteristics","sourceHeadings":["Performance Characteristics: Latency, Throughput, and the Bottlenecks"],"disposition":"pending","rationale":"Latency breakdown tables await editorial reconciliation in a dedicated operations subsection."},{"id":"tldr-summary","sourceHeadings":["TLDR Summary and Key Takeaways: What Every Developer Should Know About AI Coding Agents"],"disposition":"omitted-approved","rationale":"Internal summary section; teaching outcomes are expressed in the staged narrative and end-to-end outcome."},{"id":"run-tests-schema-detail","sourceHeadings":["OpenAI function calling: the tool schema contract"],"disposition":"pending","rationale":"Representative read_file schema included; full run_tests schema example pending review."},{"id":"key-learnings","sourceHeadings":["Summary & Key Takeaways","Lessons Learned","Closing guidance"],"destinationHeading":"Key learnings","disposition":"transformed","rationale":"Closing learnings section added so the learner narrative ends with explicit takeaways."}]},"reviewStatus":"ai-candidate","reviewerName":"Abstract Algorithms Editorial Board","reviewedAt":"2026-10-08T00:00:00Z","tags":["AI","coding agents","llm","context-window","memory-management","github copilot","claude"]},{"id":"article-dirty-read-database-anomaly","slug":"dirty-read-database-anomaly","title":"Dirty Read Explained: How Uncommitted Data Corrupts Transactions","subtitle":"How a single uncommitted write can corrupt downstream reads, cause phantom transactions, and what isolation levels prevent it","summary":"A dirty read occurs when Transaction B reads data written by Transaction A before A has committed. If A rolls back, B has made decisions on data that never officially existed. Trace the anomaly from storage-engine visibility rules through multi-service fan-out and the isolation settings that close it.","author":{"name":"Abstract Algorithms Database Team","avatarUrl":"/images/authors/team.png"},"publishedAt":"2026-04-11T17:31:09.371Z","updatedAt":"2026-10-08T00:00:00.000Z","linkedConceptSlugs":["database-isolation-levels-anomalies","transaction-isolation-distributed-acid"],"useCase":{"goal":"Prevent balance, inventory, and audit decisions from acting on uncommitted writes that may still roll back.","actorsAndComponents":["Transfer / checkout API","Balance or inventory reader service","Primary SQL database (buffer pool / MVCC versions)","Audit log and optional cache tier"],"requirements":["Readers of financial or inventory state must observe only committed row versions.","Rollback of an in-flight writer must not leave downstream decisions, caches, or audit records based on provisional values.","Approximate analytics may use weaker isolation only when the consumer contract is explicitly approximate."],"constraints":["High-concurrency OLTP with overlapping transfers and stock reservations.","Mixed engines across services; MySQL and SQL Server can still expose READ UNCOMMITTED / NOLOCK paths."],"assumptions":["PostgreSQL and Oracle exclude uncommitted versions from snapshots by design.","Application side effects outside the database transaction are not automatically undone by ROLLBACK."]},"stages":[{"stageNumber":1,"title":"Stage 1 — Name the uncertainty window","decisionOrAction":"Treat uncommitted buffer and MVCC versions as provisional until COMMIT or ROLLBACK.","linkedConceptSlugs":["database-isolation-levels-anomalies"],"conceptRoles":[{"conceptSlug":"database-isolation-levels-anomalies","roleDescription":"Defines dirty reads as observations of provisional writes that may still disappear."}],"componentBehavior":"Writers create locked pages or new row versions; readers either wait, skip locks, or consult committed snapshots.","observableOutput":"Operators can state whether a given engine/isolation pair can return in-flight values."},{"stageNumber":2,"title":"Stage 2 — Watch the race at the buffer","decisionOrAction":"Reproduce the four-beat timeline: uncommitted write, concurrent read, rollback, retained decision.","linkedConceptSlugs":["database-isolation-levels-anomalies"],"conceptRoles":[{"conceptSlug":"database-isolation-levels-anomalies","roleDescription":"Shows how READ UNCOMMITTED lets a reader observe the writer’s buffer before commit."}],"componentBehavior":"Balance service selects the provisional balance and commits an application decision while the transfer is still open.","observableOutput":"After rollback the row is restored, but the declined request and audit record remain."},{"stageNumber":3,"title":"Stage 3 — Follow the leak across services","decisionOrAction":"Stop treating cross-service reads of provisional stock as authoritative inventory truth.","linkedConceptSlugs":["transaction-isolation-distributed-acid"],"conceptRoles":[{"conceptSlug":"transaction-isolation-distributed-acid","roleDescription":"Keeps atomic rollback local to the writer while exposing why external side effects need committed inputs."}],"componentBehavior":"Inventory and order services fan out cancellations and cache entries before the warehouse reservation aborts.","observableOutput":"Customer notification and cache TTL outlive the rolled-back reservation."},{"stageNumber":4,"title":"Stage 4 — Choose the isolation floor that closes dirty reads","decisionOrAction":"Set Read Committed as the minimum isolation for OLTP financial and inventory paths.","linkedConceptSlugs":["database-isolation-levels-anomalies"],"conceptRoles":[{"conceptSlug":"database-isolation-levels-anomalies","roleDescription":"Marks Read Committed as the first SQL level that forbids dirty reads."}],"componentBehavior":"Connection pools and session defaults reject READ UNCOMMITTED for business-critical queries.","observableOutput":"Concurrent readers see only the last committed balance or stock count."},{"stageNumber":5,"title":"Stage 5 — Respect what each engine can actually do","decisionOrAction":"Configure PostgreSQL/Oracle defaults, InnoDB isolation, and SQL Server RCSI instead of NOLOCK.","linkedConceptSlugs":["transaction-isolation-distributed-acid"],"conceptRoles":[{"conceptSlug":"transaction-isolation-distributed-acid","roleDescription":"Ties engine recovery and visibility rules to the durability/isolation contract callers rely on."}],"componentBehavior":"Ops pin server/session isolation and remove unjustified NOLOCK hints.","observableOutput":"Engine matrix shows which deployments can still emit dirty reads."},{"stageNumber":6,"title":"Stage 6 — Use weak reads only where approximation is the product","decisionOrAction":"Allow READ UNCOMMITTED only for explicitly approximate analytics and monitoring.","linkedConceptSlugs":["database-isolation-levels-anomalies"],"conceptRoles":[{"conceptSlug":"database-isolation-levels-anomalies","roleDescription":"Separates intentional approximate reads from correctness-critical OLTP paths."}],"componentBehavior":"Dashboards document approximate semantics; payment and inventory APIs stay at Read Committed or higher.","observableOutput":"No approximate read populates financial ledgers, inventory commitments, or shared authoritative caches."}],"outcome":{"endToEndResult":"Business-critical readers observe only committed state; rollbacks cannot leave durable decisions based on provisional rows.","observedUserBehavior":"Valid withdrawals and checkouts are not declined because of an in-flight transfer that later aborts.","observedOperatorBehavior":"Isolation overrides and NOLOCK usage are auditable; approximate queries are labeled as such.","keyTradeoffs":["Read Committed prevents dirty reads but still allows non-repeatable reads and write skew under concurrency.","READ UNCOMMITTED / NOLOCK reduce reader blocking on some engines while accepting provisional data.","Serializable closes more anomalies but raises abort and retry rates that applications must handle."]},"alternatives":[{"title":"Pessimistic shared locks on every read","explanation":"Prevents dirty reads without MVCC by waiting for writers, at the cost of read/write blocking under contention."},{"title":"Read Committed Snapshot Isolation (RCSI) instead of NOLOCK","explanation":"On SQL Server, RCSI gives non-blocking committed reads so teams can drop NOLOCK without reintroducing dirty reads."},{"title":"Append-only ledger for balances","explanation":"Materialize balances only from committed credit/debit events so a rolled-back provisional event never becomes money movement."}],"failuresAndDegradedModes":[{"name":"Phantom refund after rolled-back debit","behavior":"A reader treats an in-flight debit as final, issues a refund, then the debit rolls back and the account is credited twice."},{"name":"Inventory cancellation from provisional zero stock","behavior":"Checkout reads an uncommitted reservation, cancels a valid order, and leaves a false stock-unavailable audit entry."},{"name":"Cache poisoning beyond the transaction window","behavior":"A dirty observation is cached with a long TTL and keeps serving the phantom after the database has rolled back."}],"evidenceRecord":{"isSourcedProductionClaim":true,"sourceUrlOrAttribution":"https://abstractalgorithms.dev/dirty-read-database-anomaly","statedAssumptions":["Teaching scenario rebuilt from the published v1 dirty-read article; claims remain pending editorial review."]},"markdownContent":"\\n## A balance check that reads an unfinished transfer\\n\\nIt is 14:03 UTC on a payment platform. The transfer service opens a transaction, debits `acc-9981` from USD 300 to USD 60, and has not committed yet. A few milliseconds later the balance service asks whether that same account can fund another withdrawal. Under `READ UNCOMMITTED`, the balance service sees USD 60, declines a valid request, and writes a false “insufficient funds” audit record. The transfer then rolls back because a downstream bank API timed out. The account still holds USD 300. The declined request was correct. The audit log is not.\\n\\nThat is a dirty read: Transaction B observed a write that Transaction A never made permanent. The damage is rarely the row itself. It is the application decision, cache entry, or event that escapes before the writer aborts.\\n\\nThis scenario follows one uncommitted debit through storage-engine visibility rules, isolation levels, multi-service fan-out, and the configuration choices that either stop the anomaly or invite it.\\n\\n```mermaid\\nsequenceDiagram\\n    title Dirty read during an uncommitted debit\\n    participant T1 as Transfer service (T1)\\n    participant DB as Database engine\\n    participant T2 as Balance service (T2)\\n    T1->>DB: BEGIN; UPDATE accounts SET balance = 60\\n    Note over DB: New value is in the write buffer / new row version\\n    T2->>DB: SELECT balance WHERE id = 9981\\n    DB-->>T2: 60 (dirty, if READ UNCOMMITTED)\\n    Note over T2: Declines withdrawal and writes audit\\n    T1->>DB: ROLLBACK\\n    Note over DB: Balance restored to 300\\n    Note over T2: Decision already committed outside the row\\n```\\n\\n## Stage 1 — Name the uncertainty window\\n\\nCommitted data is durable and visible to later transactions. Uncommitted data is provisional: it may exist in a buffer, undo chain, or new MVCC version, and the writer can still erase it with `ROLLBACK`. A dirty read is a read of that provisional middle state.\\n\\nTwo engine families expose the window differently:\\n\\n- Lock-based engines prevent dirty reads when readers take shared locks that conflict with the writer’s exclusive lock. `READ UNCOMMITTED` skips that shared lock and lets the reader touch the buffered page.\\n- MVCC engines tag each new row version with the writing transaction id. A reader’s snapshot includes only committed creators, so an in-flight version is invisible and the previous committed version is returned instead.\\n\\n``\\n    [*] --> Uncommitted: Writer mutates the row\\n    Uncommitted --> Committed: COMMIT\\n    Uncommitted --> RolledBack: ROLLBACK\\n    Committed --> [*]: Permanent for later readers\\n    RolledBack --> [*]: Prior committed value restored\\n```\\n\\nThe mental model is not “the database stored a wrong number.” It is “another transaction acted on a future that was cancelled.”\\n\\n## Stage 2 — Watch the race at the buffer\\n\\nThe dirty-read timeline has four beats: T1 writes without committing, T2 reads the provisional value, T1 rolls back, and T2 keeps the decision it already made. From the engine’s point of view T2’s later `COMMIT` can still be valid. The bug lives in application logic that treated an uncommitted observation as durable truth.\\n\\n```sql\\n-- T1 (transfer)\\nBEGIN;\\nUPDATE accounts SET balance = 60 WHERE id = 9981;\\n-- still open...\\n\\n-- T2 (balance check) at READ UNCOMMITTED\\nBEGIN;\\nSELECT balance FROM accounts WHERE id = 9981; -- may return 60\\n-- declines a second withdrawal based on that value\\nCOMMIT;\\n\\n-- T1\\nROLLBACK; -- balance returns to 300; T2\'s decision remains\\n```\\n\\nOn a locking engine at `READ UNCOMMITTED`, T2 never waits for T1’s exclusive lock. On PostgreSQL, even an attempted `READ UNCOMMITTED` session is upgraded to `READ COMMITTED`, so T2 would still see the last committed balance of 300. Engine architecture decides whether the anomaly is possible at all.\\n\\n## Stage 3 — Follow the leak across services\\n\\nInside one database connection the harm is already real. Across microservices it becomes a data-contract violation that outruns the rollback.\\n\\nA warehouse reservation writes stock to zero and stays uncommitted. An inventory service reads that zero under a weak isolation setting and tells the order service the SKU is unavailable. Shipping and notification pipelines act on that answer. When the warehouse rolls back, stock is 1 again, but the customer already received a cancellation and the audit trail contains a phantom stock-out.\\n\\n``\\n    A[Warehouse service] -->|BEGIN reserve SKU-4421| B[Uncommitted write buffer]\\n    B -->|Weak isolation read| C[Inventory service]\\n    C -->|Reports zero available| D[Order service]\\n    D -->|Queues cancellation| E[Shipping / notify]\\n    A -->|ROLLBACK| F[Stock restored to 1]\\n    F -.->|Too late| E\\n```\\n\\nCaches make the window longer. A Redis or Memcached entry populated from a dirty read can serve the phantom value long after the source transaction disappeared. Treat “committed read → then cache” as part of the contract for financial and inventory paths.\\n\\n## Stage 4 — Choose the isolation floor that closes dirty reads\\n\\nSQL isolation levels are defined by the anomalies they allow. Dirty reads are permitted only at `READ UNCOMMITTED`. `READ COMMITTED` is the first level that forbids them, and it is the default on PostgreSQL, Oracle, and SQL Server.\\n\\n| Isolation level | Dirty read | Non-repeatable read | Phantom read | Write skew |\\n| --- | :---: | :---: | :---: | :---: |\\n| Read Uncommitted | Possible | Possible | Possible | Possible |\\n| Read Committed | Prevented | Possible | Possible | Possible |\\n| Repeatable Read | Prevented | Prevented | Possible* | Possible* |\\n| Serializable | Prevented | Prevented | Prevented | Prevented |\\n\\n\\\\*InnoDB Repeatable Read also blocks many phantoms with gap locks; the SQL standard still allows phantoms at that level.\\n\\nSerializable removes more anomaly classes, but under contention it increases aborts and retries. For most OLTP work, Read Committed is the correct floor for dirty-read protection. Raise isolation when the workload also needs stable multi-statement snapshots or serializable conflict detection.\\n\\n## Stage 5 — Respect what each engine can actually do\\n\\nThe SQL standard allows dirty reads at `READ UNCOMMITTED`. Implementations diverge:\\n\\n| Database | Default isolation | Can emit dirty reads? |\\n| --- | --- | :---: |\\n| PostgreSQL | Read Committed | No — MVCC excludes uncommitted versions; `READ UNCOMMITTED` is upgraded |\\n| MySQL InnoDB | Repeatable Read | Yes — only at `READ UNCOMMITTED` |\\n| Oracle | Read Committed | No — that is the minimum level |\\n| SQL Server | Read Committed | Yes — via `READ UNCOMMITTED` or `NOLOCK` |\\n\\nPostgreSQL and Oracle are architecturally closed to dirty reads. MySQL and SQL Server are not, and SQL Server’s `WITH (NOLOCK)` is the most common accidental opt-in: developers add it for “faster reads” and silently accept dirty, non-repeatable, and phantom reads together.\\n\\n```ini\\n# postgresql.conf — safe default already prevents dirty reads\\ndefault_transaction_isolation = \'read committed\'\\n```\\n\\n```ini\\n# my.cnf — keep InnoDB at least at READ-COMMITTED for OLTP\\n[mysqld]\\ntransaction_isolation = READ-COMMITTED\\n```\\n\\n```sql\\n-- SQL Server: prefer RCSI over NOLOCK for non-blocking committed reads\\nALTER DATABASE YourDatabase SET READ_COMMITTED_SNAPSHOT ON;\\n```\\n\\n## Stage 6 — Use weak reads only where approximation is the product\\n\\nDirty reads are sometimes an accepted trade-off when the consumer already labels the number as approximate: live “users online” counters, coarse monitoring scans, or batch reports that must not contend with OLTP writers. In those cases document the isolation choice on the endpoint or query, and never feed the result into payments, inventory commitments, compliance ledgers, or shared caches that other services treat as authoritative.\\n\\nDefenses, cheapest first:\\n\\n1. Audit for explicit `READ UNCOMMITTED`, `NOLOCK`, and ORM isolation overrides; remove unjustified ones.\\n2. Pin Read Committed (or higher) at the pool / data-source layer on MySQL and SQL Server.\\n3. Use Repeatable Read / Serializable snapshots for long reporting queries on MVCC engines instead of weakening isolation.\\n4. Add optimistic version checks when you cannot raise isolation but must detect lost updates.\\n5. Prefer append-only ledgers for balances that must reconstruct only from committed events.\\n\\n## End-to-end outcome\\n\\nAfter this walkthrough you should be able to:\\n\\n- Explain why “dirty” means provisional, not merely incorrect.\\n- Trace a dirty read from an uncommitted buffer through an application decision and optional cache fan-out.\\n- Name Read Committed as the isolation floor that closes the anomaly.\\n- Distinguish engines that cannot emit dirty reads from those that can at `READ UNCOMMITTED` / `NOLOCK`.\\n- Choose intentional approximate reads without putting them on financial or inventory paths.\\n\\n## Alternatives considered\\n\\n**Exclusive locking for every read.** Waiting on the writer’s exclusive lock prevents dirty reads without MVCC, but read throughput collapses under write contention.\\n\\n**Always Serializable.** Removes dirty reads and most other anomalies, at the cost of higher abort/retry rates that many OLTP APIs are not prepared to handle.\\n\\n**RCSI or native MVCC at Read Committed.** Preferred alternative to `NOLOCK`: non-blocking readers that still see only committed versions.\\n\\n## Failure and degraded modes\\n\\n**Phantom refunds and double credits.** A payment path refunds against an in-flight debit that later rolls back, leaving both the restored balance and the refund.\\n\\n**Lost sales and poisoned audits.** Checkout reads a provisional zero stock, turns away a buyer, and records a stock-out that never existed after rollback.\\n\\n**Cache poisoning.** A short dirty observation is stored with a multi-minute TTL and keeps serving the phantom after the database has already healed.\\n\\n## Key learnings\\n\\n- A dirty read is acting on a provisional write that may still roll back — the danger is the decision, cache, or event that escapes, not only the row value.\\n- Read Committed is the isolation floor that forbids dirty reads; it is the default on PostgreSQL, Oracle, and SQL Server.\\n- PostgreSQL and Oracle cannot emit dirty reads by design; MySQL and SQL Server can at READ UNCOMMITTED, and SQL Server often does via NOLOCK.\\n- Prefer RCSI or native MVCC committed reads over NOLOCK when you need non-blocking readers without provisional data.\\n- Use READ UNCOMMITTED only for explicitly approximate analytics — never for payments, inventory commitments, compliance logs, or authoritative caches.\\n","sourceMigration":{"sourceIds":["src-dirty-read-database-anomaly"],"sourceVersion":"2026-07-26T19:30:26.909Z","sourceUrl":"https://abstractalgorithms.dev/dirty-read-database-anomaly","reviewState":"pending-review","coverage":[{"id":"opening-failure","sourceHeadings":["The $240 Phantom Refund: A Real Production Failure"],"destinationHeading":"A balance check that reads an unfinished transfer","disposition":"transformed"},{"id":"why-dirty","sourceHeadings":["Why Uncommitted Data Is Called \\"Dirty\\""],"destinationHeading":"Stage 1 — Name the uncertainty window","disposition":"transformed"},{"id":"mechanics-timeline","sourceHeadings":["The Mechanics of a Dirty Read: A Step-by-Step Transaction Timeline"],"destinationHeading":"Stage 2 — Watch the race at the buffer","disposition":"transformed"},{"id":"engine-internals","sourceHeadings":["Deep Dive: How the Database Engine Permits or Blocks Dirty Reads","The Internals: Row Visibility in Lock-Based vs. MVCC Engines","Performance Analysis: The Cost of Preventing Dirty Reads"],"destinationHeading":"Stage 2 — Watch the race at the buffer","disposition":"transformed","rationale":"Engine visibility rules are woven into Stages 1–2 rather than kept as a separate long internals essay."},{"id":"multi-service","sourceHeadings":["How Dirty Reads Propagate Through a Multi-Service Architecture"],"destinationHeading":"Stage 3 — Follow the leak across services","disposition":"transformed"},{"id":"isolation-spectrum","sourceHeadings":["The Isolation Level Spectrum: Which Levels Draw the Line on Dirty Reads"],"destinationHeading":"Stage 4 — Choose the isolation floor that closes dirty reads","disposition":"transformed"},{"id":"engine-matrix","sourceHeadings":["How PostgreSQL, MySQL, Oracle, and SQL Server Each Handle Dirty Reads"],"destinationHeading":"Stage 5 — Respect what each engine can actually do","disposition":"transformed"},{"id":"intentional-ru","sourceHeadings":["When Read Uncommitted Is Used Intentionally — and Safely"],"destinationHeading":"Stage 6 — Use weak reads only where approximation is the product","disposition":"transformed"},{"id":"defenses-and-config","sourceHeadings":["Architectural Defenses Against Dirty Read Corruption","PostgreSQL and MySQL: Configuring Isolation Levels at the Server and Session Level"],"destinationHeading":"Stage 6 — Use weak reads only where approximation is the product","disposition":"transformed"},{"id":"failures","sourceHeadings":["What Dirty Reads Actually Break Downstream: Failure Modes in Production"],"destinationHeading":"Failure and degraded modes","disposition":"transformed"},{"id":"summary","sourceHeadings":["Summary & Key Takeaways","Lessons Learned from Dirty Read Incidents"],"destinationHeading":"End-to-end outcome","disposition":"transformed"},{"id":"detection-queries","sourceHeadings":["Finding Dirty Read Exposure in a Running Production Database"],"disposition":"pending","rationale":"pg_stat_activity / lock-wait detection queries need editor review before inclusion in the learner narrative."},{"id":"checkout-walkthrough-detail","sourceHeadings":["Tracing a Dirty Read Through a Real E-Commerce Checkout Scenario"],"disposition":"pending","rationale":"The multi-service stage covers the checkout race; the full timed Phase 1/Phase 2 walkthrough awaits review for length."},{"id":"decision-matrix-rows","sourceHeadings":["Choosing the Right Isolation Level: When Dirty Read Protection Is Worth the Cost"],"disposition":"pending","rationale":"Stage 4 and Stage 6 summarize the decision; the full situation matrix is pending editorial compression."},{"id":"source-code-and-diagram-inventory","sourceHeadings":["All fenced code examples and legacy diagram blocks"],"disposition":"pending","rationale":"V2 narrative includes remapped mermaid/SQL/ini examples; individual legacy blocks are not yet one-to-one reconciled."},{"id":"key-learnings","sourceHeadings":["Summary & Key Takeaways","Lessons Learned","Closing guidance"],"destinationHeading":"Key learnings","disposition":"transformed","rationale":"Closing learnings section added so the learner narrative ends with explicit takeaways."}]},"reviewStatus":"ai-candidate","tags":["Databases","Transactions","Isolation","Dirty Read","MVCC","PostgreSQL","MySQL","SQL Server"]}]').filter(e=>!!e.id&&!!e.slug||(console.warn("[ScenarioArticlesLoader] Skipping corrupt article record without id/slug"),!1));function o(){return a}let i={"redis-event-loop-deep-dive":"how-redis-internals-work","kafka-event-streaming-patterns":"how-kafka-works"};function s(e){var t;let n=null!==(t=i[e])&&void 0!==t?t:e;return a.find(t=>t.slug===n||t.id===n||t.slug===e||t.id===e)}function r(e){let t=e.toLowerCase();return a.filter(e=>e.linkedConceptSlugs.some(e=>e.toLowerCase()===t))}s("e2e-high-throughput-e-commerce-inventory-and-checkout"),s("acid-properties-in-sql-databases"),s("bloom-filters-explained"),s("consistency-patterns-in-distributed-systems"),s("consensus-algorithms-raft-paxos"),s("how-redis-internals-work"),s("api-rate-limiting-strategies"),s("how-kafka-works"),s("how-ai-coding-agents-work"),s("dirty-read-database-anomaly")}}]);